    #[test]
    fn test_reproposed_block_passes_validation() {
        // A receiving validator (possibly already at view=31) must still accept a
        // re-proposal carrying the original round — validation only keys off
        // proposer_for(header.round()), not the receiver's view.
        let (state, topology_schedule) = make_multi_validator_state();
        let header = make_header_at_height(BlockHeight::new(1), state.now.as_millis());

        assert!(
            validate_header(
                Some(topology_schedule.head()),
                Some(topology_schedule.head().as_ref()),
                state.local_shard,
                &header,
                state.committed_height,
                state.now,
            )
            .is_ok()
        );
    }

    #[test]
    fn test_reproposed_block_with_wrong_proposer_fails_validation() {
        let (state, topology_schedule) = make_multi_validator_state();
        // proposer_for(1) = ValidatorId::new(1), but the header claims ValidatorId::new(3).
        let header = {
            let __h = make_header_at_height(BlockHeight::new(1), state.now.as_millis());
            BlockHeader::new(BlockHeaderParts {
                shard_id: __h.shard_id(),
                height: __h.height(),
                parent_block_hash: __h.parent_block_hash(),
                parent_qc: __h.parent_qc().clone().into(),
                proposer: ValidatorId::new(3),
                timestamp: __h.timestamp(),
                round: __h.round(),
                is_fallback: __h.is_fallback(),
                state_root: __h.state_root(),
                body_root: __h.body_root(),
                provision_tx_roots: __h.provision_tx_roots().clone(),
                txs_in_flight: __h.txs_in_flight(),
                load: __h.load(),
                ..Default::default()
            })
        };

        let result = validate_header(
            Some(topology_schedule.head()),
            Some(topology_schedule.head().as_ref()),
            state.local_shard,
            &header,
            state.committed_height,
            state.now,
        );
        assert!(
            result.is_err(),
            "Block with wrong proposer for round should fail validation"
        );
        assert!(
            result.unwrap_err().contains("wrong proposer"),
            "Error should mention wrong proposer"
        );
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // Extended View Change Tests
    // ═══════════════════════════════════════════════════════════════════════════

    #[test]
    fn test_qc_formed_proposes_empty_block_for_finalization() {
        // Under the 2-chain commit rule, block N+1 is what certifies block N.
        // After a QC forms we must propose N+1 immediately — even with no
        // content — or finalization of N stalls.
        let (mut state, topology_schedule) = make_test_state();
        state.set_time(LocalTimestamp::from_millis(100_000));
        // Parent tree must be available or try_propose defers.
        state.committed_height = BlockHeight::new(3);
        state.verification.on_block_persisted(BlockHeight::new(3));
        // Rounds increase per block: height 4 is proposed at round 4, where
        // proposer_for(4, 4) = validator 0 (local).
        state.view_change.view = Round::new(4);

        // Block 3 is the committed tip and its header is in memory, so the
        // QC over it is adopted and the proposal extends it.
        let block_3 = make_header_at_height(BlockHeight::new(3), 99_000);
        let block_3_hash = block_3.hash();
        state.committed_hash = block_3_hash;
        state.pending_blocks.insert(PendingBlock::from_manifest(
            block_3,
            BlockManifest::default(),
            LocalTimestamp::ZERO,
        ));

        let qc = {
            let __qc = make_test_qc(block_3_hash, BlockHeight::new(3));
            // SAFETY: synthetic test fixture, no real signature.
            Verified::<QuorumCertificate>::new_unchecked_for_test(QuorumCertificate::new(
                __qc.block_hash(),
                __qc.shard_id(),
                __qc.height(),
                BlockHash::from_raw(Hash::from_bytes(b"block_2")),
                __qc.round(),
                __qc.signers().clone(),
                __qc.aggregated_signature(),
                __qc.weighted_timestamp(),
            ))
        };

        let actions = state.on_qc_formed(&topology_schedule, block_3_hash, &qc, |_| {
            ProposalInputs::default()
        });

        // Should emit BuildProposal for height 4 even with empty content.
        let has_build_proposal = actions.iter().any(
            |a| matches!(a, Action::BuildProposal { height, .. } if height == &BlockHeight::new(4)),
        );

        assert!(
            has_build_proposal,
            "Should propose empty block immediately after QC formation to advance finalization"
        );
    }

    /// A seat about to certify the block at height 3 and lead the round
    /// after it, holding that block's tree: the committed tip at height
    /// 2 whose header reads `tip_in_flight`, the uncommitted block on it
    /// carrying `carried` whose header reads `block_in_flight`, and the
    /// QC over that block.
    fn about_to_certify(
        tip_in_flight: u64,
        block_in_flight: u64,
        carried: &[Transaction],
    ) -> (
        ShardCoordinator,
        TopologySchedule,
        Verified<QuorumCertificate>,
    ) {
        let (mut state, schedule, qc) =
            about_to_certify_without_its_tree(tip_in_flight, block_in_flight, carried);
        state.verification.on_block_persisted(qc.height());
        (state, schedule, qc)
    }

    /// [`about_to_certify`], with the certified block's tree not yet in
    /// hand.
    fn about_to_certify_without_its_tree(
        tip_in_flight: u64,
        block_in_flight: u64,
        carried: &[Transaction],
    ) -> (
        ShardCoordinator,
        TopologySchedule,
        Verified<QuorumCertificate>,
    ) {
        test_utils::install_stub_protocol_statics();
        let (mut state, schedule) = make_test_state();
        state.set_time(LocalTimestamp::from_millis(30_000));
        let header = |height: u64, parent_qc: QuorumCertificate, in_flight: u64| {
            BlockHeader::new(BlockHeaderParts {
                height: BlockHeight::new(height),
                parent_block_hash: parent_qc.block_hash(),
                parent_qc: parent_qc.into(),
                proposer: ValidatorId::new(height % 4),
                timestamp: ProposerTimestamp::from_millis(10_000 * height),
                round: Round::new(height),
                txs_in_flight: TxsInFlight::new(in_flight),
                ..Default::default()
            })
        };
        let qc_over = |header: &BlockHeader| {
            QuorumCertificate::new(
                header.hash(),
                ShardId::ROOT,
                header.height(),
                header.parent_block_hash(),
                header.round(),
                SignerBitfield::empty(),
                AggregateSignature::ZERO,
                WeightedTimestamp::from_millis(10_000 * header.height().inner()),
            )
        };

        let tip = header(
            2,
            QuorumCertificate::genesis(ShardId::ROOT, ChainOrigin::root(WeightedTimestamp::ZERO)),
            tip_in_flight,
        );
        state.committed_height = tip.height();
        state.committed_hash = tip.hash();
        let block = header(3, qc_over(&tip), block_in_flight);
        state.pending_blocks.insert(PendingBlock::from_manifest(
            tip,
            BlockManifest::default(),
            LocalTimestamp::ZERO,
        ));
        let qc = Verified::new_unchecked_for_test(qc_over(&block));
        let block = carrying(
            Block::Live {
                header: block,
                transactions: Arc::new(Capped::empty()),
                certificates: Arc::new(Capped::empty()),
                provisions: Arc::new(Capped::empty()),
                abandonment_records: Arc::new(Capped::empty()),
                state_claims: Arc::new(Capped::empty()),
                tick_manifest: Arc::new(Capped::empty()),
                terms: Arc::new(Capped::empty()),
                witness_sources: Arc::new(WitnessSources::empty()),
            },
            carried,
            Vec::new(),
        );
        install_complete_block(&mut state, &block);
        (state, schedule, qc)
    }

    /// A transaction admission takes on a root-shard block anchored at
    /// `anchor_ms`.
    fn admissible_at(anchor_ms: u64) -> Arc<Verified<Transaction>> {
        test_utils::install_stub_protocol_statics();
        let payer = test_utils::test_principal(0x21);
        Arc::new(Verified::new_unchecked_for_test(
            test_utils::stub_transaction(
                payer,
                &[payer.address()],
                1_000,
                TimestampRange::new(
                    WeightedTimestamp::from_millis(anchor_ms.saturating_sub(1_000)),
                    WeightedTimestamp::from_millis(anchor_ms + 1_000),
                ),
            ),
        ))
    }

    /// A gather that records it was asked and offers `tx` alone.
    fn offering<'a>(
        asked: &'a Cell<bool>,
        tx: &'a Arc<Verified<Transaction>>,
    ) -> impl Fn(&ProposalAsk<'_>) -> ProposalInputs + 'a {
        |_| {
            asked.set(true);
            ProposalInputs {
                ready_txs: vec![Arc::clone(tx)],
                ..ProposalInputs::default()
            }
        }
    }

    /// A pool on the root shard holding `transactions`.
    fn pool_of(schedule: &TopologySchedule, transactions: &[Transaction]) -> MempoolCoordinator {
        let mut mempool = MempoolCoordinator::new(ShardId::ROOT);
        for tx in transactions {
            mempool.on_transaction_gossip(
                schedule.head(),
                Arc::new(Verified::new_unchecked_for_test(tx.clone())),
                LocalTimestamp::ZERO,
            );
        }
        mempool
    }

    /// The transactions of the proposal `actions` build, in block order.
    fn proposed(actions: &[Action]) -> Vec<TxHash> {
        actions
            .iter()
            .find_map(|action| match action {
                Action::BuildProposal { transactions, .. } => {
                    Some(transactions.iter().map(|tx| tx.hash()).collect())
                }
                _ => None,
            })
            .expect("the seat leads the round the QC opens")
    }

    /// The ready set `mempool` offers a block built under `ask`, as a
    /// proposal's whole content.
    fn ready_from(
        mempool: &MempoolCoordinator,
        now: LocalTimestamp,
        ask: &ProposalAsk<'_>,
    ) -> ProposalInputs {
        ProposalInputs {
            ready_txs: mempool.ready_transactions(MAX_TXS_PER_BLOCK, &ask.intake, now, |_| true),
            ..ProposalInputs::default()
        }
    }

    /// A seat is asked for a block's content only once it has passed the
    /// proposer gates and resolved the parent of a block that carries
    /// content. The seat that leads the round the QC opens is asked
    /// once, at the block the QC certifies; a seat that does not lead it
    /// adopts the same QC and is never asked, on the QC or on a retry,
    /// and neither is the leader again while its build is in flight.
    #[test]
    fn only_a_seat_past_the_proposer_gates_is_asked_for_content() {
        let asked = Cell::new(0_usize);
        let counting = |ask: &ProposalAsk<'_>| {
            asked.set(asked.get() + 1);
            assert_eq!(ask.intake.in_flight, TxsInFlight::new(7));
            ProposalInputs::default()
        };

        let (mut leader, schedule, qc) = about_to_certify(3, 7, &[]);
        // A commit with content behind the tip keeps the leader eager.
        leader.eager_through = qc.height();
        let actions = leader.on_qc_formed(&schedule, qc.block_hash(), &qc, counting);
        assert!(proposed(&actions).is_empty());
        assert_eq!(asked.get(), 1, "the leader is asked once");
        let retry = leader.try_propose(&schedule, counting);
        assert!(retry.is_empty(), "the build is in flight: {retry:?}");
        assert_eq!(asked.get(), 1, "and not again while it builds");

        asked.set(0);
        let (mut other, schedule, qc) = about_to_certify(3, 7, &[]);
        other.reseat_sole_signer(ValidatorId::new(1));
        let mut actions = other.on_qc_formed(&schedule, qc.block_hash(), &qc, counting);
        actions.extend(other.try_propose(&schedule, counting));
        assert_eq!(
            other.latest_qc().map(|qc| qc.block_hash()),
            Some(qc.block_hash())
        );
        assert!(
            !actions
                .iter()
                .any(|action| matches!(action, Action::BuildProposal { .. })),
            "a seat that does not lead the round builds nothing: {actions:?}"
        );
        assert_eq!(asked.get(), 0, "and is never asked");
    }

    /// A build known beforehand not to go out asks for nothing: one held
    /// back behind a retained tip the harvest has not reached, one whose
    /// round skips rounds no certificate justifies, and one that parks
    /// on its parent's tree, which leaves its slot deferred.
    #[test]
    fn a_build_that_will_not_go_out_asks_for_nothing() {
        let asked = Cell::new(false);
        let asking = |_: &ProposalAsk<'_>| {
            asked.set(true);
            ProposalInputs::default()
        };
        let builds = |actions: &[Action]| {
            actions
                .iter()
                .any(|action| matches!(action, Action::BuildProposal { .. }))
        };
        let next = BlockHeight::new(4);

        let (mut held_back, schedule, qc) = about_to_certify(3, 7, &[]);
        held_back.retained_tip = Some(RetainedTip::Offered(BlockHeight::new(9)));
        let actions = held_back.on_qc_formed(&schedule, qc.block_hash(), &qc, asking);
        let round = held_back.view_change.view;
        assert!(held_back.can_propose(&schedule, next, round));
        assert!(held_back.proposal_frame(&schedule, next, round).is_none());
        assert!(!builds(&actions) && !asked.get(), "behind a retained tip");

        // The QC is adopted from a seat that does not lead its round,
        // which then leads a round five past it with no certificate held.
        let (mut skipping, schedule, qc) = about_to_certify(3, 7, &[]);
        skipping.reseat_sole_signer(ValidatorId::new(1));
        let _ = skipping.on_qc_formed(&schedule, qc.block_hash(), &qc, asking);
        let round = Round::new(qc.round().inner() + 5);
        skipping.view_change.view = round;
        skipping.reseat_sole_signer(schedule.head().proposer_for(ShardId::ROOT, round));
        assert!(skipping.can_propose(&schedule, next, round));
        let frame = skipping
            .proposal_frame(&schedule, next, round)
            .expect("the block's frame resolves");
        assert!(frame.substate.is_ok() && skipping.build_tree_held());
        assert!(!skipping.extends_empty(&schedule, &frame));
        assert!(
            !frame.rounds_justified(round),
            "only the unproven rounds stop it"
        );
        let actions = skipping.try_propose(&schedule, asking);
        assert!(
            !builds(&actions) && !asked.get(),
            "skipping rounds unproven"
        );

        let (mut parked, schedule, qc) = about_to_certify_without_its_tree(3, 7, &[]);
        let actions = parked.on_qc_formed(&schedule, qc.block_hash(), &qc, asking);
        assert!(
            !builds(&actions) && !asked.get(),
            "parked on the parent's tree"
        );
        assert_eq!(
            parked.proposal.deferred().map(|slot| slot.height),
            Some(next)
        );
        assert_eq!(
            parked.verification.deferred_proposal(),
            Some((qc.block_hash(), qc.height()))
        );
    }

    /// The four pooled transactions of the QC-path cases, in hash order.
    fn pooled() -> Vec<Transaction> {
        let mut txs: Vec<Transaction> = (1..=4).map(test_transaction).collect();
        txs.sort_by_key(Transaction::hash);
        txs
    }

    /// A seat leading the round after the QC over the block at height 4,
    /// with the committed tip at height 2 and the blocks at 3 and 4 each
    /// carrying one claim of a sibling's: the blocks, and the QC.
    fn leading_on_two_carriers() -> (
        ShardCoordinator,
        TopologySchedule,
        [Block; 2],
        Verified<QuorumCertificate>,
    ) {
        test_utils::install_stub_protocol_statics();
        let (mut state, schedule) = make_test_state();
        state.set_time(LocalTimestamp::from_millis(40_000));
        let header = |height: u64, parent_qc: QuorumCertificate| {
            BlockHeader::new(BlockHeaderParts {
                height: BlockHeight::new(height),
                parent_block_hash: parent_qc.block_hash(),
                parent_qc: parent_qc.into(),
                proposer: ValidatorId::new(height % 4),
                timestamp: ProposerTimestamp::from_millis(10_000 * height),
                round: Round::new(height),
                ..Default::default()
            })
        };
        let qc_over = |header: &BlockHeader| {
            QuorumCertificate::new(
                header.hash(),
                ShardId::ROOT,
                header.height(),
                header.parent_block_hash(),
                header.round(),
                SignerBitfield::empty(),
                AggregateSignature::ZERO,
                WeightedTimestamp::from_millis(10_000 * header.height().inner()),
            )
        };
        let carrying = |header: BlockHeader, seed: u8| {
            let anchor = Anchor {
                shard: ShardId::leaf(1, 1),
                height: BlockHeight::new(2),
                state_root: StateRoot::from_raw(Hash::from_bytes(b"sibling")),
                ts: WeightedTimestamp::from_millis(2_000),
            };
            let claim = StateClaim::new(
                anchor,
                [(test_utils::test_key(seed), Inclusion::Present([seed; 32]))],
                MerkleInclusionProof::dummy(),
            );
            Block::Live {
                header,
                transactions: Arc::new(Capped::empty()),
                certificates: Arc::new(Capped::empty()),
                provisions: Arc::new(Capped::empty()),
                abandonment_records: Arc::new(Capped::empty()),
                state_claims: Arc::new(Capped::from_array([claim])),
                tick_manifest: Arc::new(Capped::empty()),
                terms: Arc::new(Capped::empty()),
                witness_sources: Arc::new(WitnessSources::empty()),
            }
        };

        let tip = header(
            2,
            QuorumCertificate::genesis(ShardId::ROOT, ChainOrigin::root(WeightedTimestamp::ZERO)),
        );
        state.committed_height = tip.height();
        state.committed_hash = tip.hash();
        let committing = carrying(header(3, qc_over(&tip)), 1);
        let certified = carrying(header(4, qc_over(committing.header())), 2);
        state.pending_blocks.insert(PendingBlock::from_manifest(
            tip,
            BlockManifest::default(),
            LocalTimestamp::ZERO,
        ));
        install_complete_block(&mut state, &committing);
        install_complete_block(&mut state, &certified);
        let qc = Verified::new_unchecked_for_test(qc_over(certified.header()));
        state.verification.on_block_persisted(qc.height());
        state.reseat_sole_signer(
            schedule
                .head()
                .proposer_for(ShardId::ROOT, qc.round().next()),
        );
        (state, schedule, [committing, certified], qc)
    }

    /// The proposal a QC over `B+1` opens is asked with what `B` and
    /// `B+1` carry in their claims, where execution has folded neither:
    /// both above the committed tip while `B`'s commit is in flight, and
    /// `B` from the committed blocks once it lands. What execution has
    /// folded through is passed over by nothing.
    #[test]
    fn a_proposal_on_a_formed_qc_skips_what_the_block_it_commits_carried() {
        let (mut state, schedule, [committing, certified], qc) = leading_on_two_carriers();
        let (in_committing, in_certified) =
            (&committing.state_claims()[0], &certified.state_claims()[0]);
        let both: BTreeSet<SubstateKey> = [in_committing, in_certified]
            .into_iter()
            .flat_map(StateClaim::keys)
            .collect();
        let carried_at = |carried: &CarriedClaims| {
            carried
                .cells_at(&in_committing.anchor)
                .cloned()
                .unwrap_or_default()
        };
        let asked = Cell::new(false);
        let actions = state.on_qc_formed(&schedule, qc.block_hash(), &qc, |ask| {
            asked.set(true);
            assert_eq!(
                carried_at(&ask.carried_above(BlockHeight::new(2))),
                both,
                "both unfolded blocks above the committed tip",
            );
            ProposalInputs::default()
        });
        assert!(
            asked.get(),
            "the seat leads the round the QC opens: {actions:?}"
        );

        // B's commit lands; execution has not folded it.
        state.committed_carried.record(
            committing.height(),
            CarriedClaims::of(ShardId::ROOT, committing.state_claims()),
        );
        state.committed_height = committing.height();
        state.committed_hash = committing.hash();
        let round = qc.round().next();
        let frame = state
            .proposal_frame(&schedule, qc.height().next(), round)
            .expect("the block's frame resolves");
        let mut seen = Vec::new();
        state
            .gathered_payload(
                &schedule,
                &frame,
                Some(|ask: &ProposalAsk<'_>| {
                    seen.push(carried_at(&ask.carried_above(BlockHeight::new(2))));
                    seen.push(carried_at(&ask.carried_above(committing.height())));
                    ProposalInputs::default()
                }),
            )
            .expect("the chain to the parent is held");
        assert_eq!(
            seen[0], both,
            "B from the committed blocks, B+1 above the tip"
        );
        assert_eq!(
            seen[1],
            in_certified.keys().into_iter().collect(),
            "a folded B is passed over by nothing",
        );
    }

    /// The block a QC certifies is the parent of the proposal the QC
    /// opens, and its transactions stay pending in the pool until it
    /// commits. The certified block leaves two places and carries the
    /// pool's first two transactions; the ask names both as carried, so
    /// the two places go to the two the block does not carry.
    #[test]
    fn the_proposal_a_qc_opens_passes_over_what_the_certified_block_carries() {
        let txs = pooled();
        let (carried, fresh) = txs.split_at(2);
        let fresh: Vec<TxHash> = fresh.iter().map(Transaction::hash).collect();

        let (mut state, schedule, qc) =
            about_to_certify(MAX_UNSETTLED_TXS - 2, MAX_UNSETTLED_TXS - 2, carried);
        let mempool = pool_of(&schedule, &txs);
        let now = state.now;
        let actions = state.on_qc_formed(&schedule, qc.block_hash(), &qc, |ask| {
            assert_eq!(ask.intake.carried.len(), 2);
            ready_from(&mempool, now, ask)
        });
        assert_eq!(
            state.latest_qc().map(|qc| qc.block_hash()),
            Some(qc.block_hash())
        );
        assert_eq!(proposed(&actions), fresh);
    }

    /// The tip stands at the drain's budget and the block a QC certifies
    /// leaves four places. The ask reads the drain off the certified
    /// block, so the proposal the QC opens carries all four pooled
    /// transactions.
    #[test]
    fn the_proposal_a_qc_opens_takes_the_places_the_certified_block_freed() {
        let txs = pooled();
        let fresh: Vec<TxHash> = txs.iter().map(Transaction::hash).collect();

        let (mut state, schedule, qc) =
            about_to_certify(MAX_UNSETTLED_TXS, MAX_UNSETTLED_TXS - 4, &[]);
        let mempool = pool_of(&schedule, &txs);
        let now = state.now;
        let actions = state.on_qc_formed(&schedule, qc.block_hash(), &qc, |ask| {
            assert_eq!(
                ask.intake.in_flight,
                TxsInFlight::new(MAX_UNSETTLED_TXS - 4)
            );
            ready_from(&mempool, now, ask)
        });
        assert_eq!(proposed(&actions), fresh);
    }

    /// A one-member committee's own vote is its quorum, so no vote round
    /// trip spaces its blocks: the proposal after a QC it formed alone waits
    /// out the pace, then goes ahead.
    #[test]
    fn a_solo_qc_paces_the_next_proposal() {
        let (mut state, topology_schedule) = make_test_state_with_validators(1);
        let formed_at = LocalTimestamp::from_millis(100_000);
        state.set_time(formed_at);
        state.committed_height = BlockHeight::new(3);
        state.verification.on_block_persisted(BlockHeight::new(3));
        state.view_change.view = Round::new(4);
        let block_3 = make_header_at_height(BlockHeight::new(3), 99_000);
        let block_3_hash = block_3.hash();
        state.committed_hash = block_3_hash;
        state.pending_blocks.insert(PendingBlock::from_manifest(
            block_3,
            BlockManifest::default(),
            formed_at,
        ));
        let mut signers = SignerBitfield::new(1);
        signers.set(0);
        // SAFETY: synthetic test fixture, no real signature.
        let qc = Verified::<QuorumCertificate>::new_unchecked_for_test(QuorumCertificate::new(
            block_3_hash,
            ShardId::ROOT,
            BlockHeight::new(3),
            BlockHash::from_raw(Hash::from_bytes(b"block_2")),
            Round::new(3),
            signers,
            AggregateSignature::ZERO,
            WeightedTimestamp::from_millis(100_000),
        ));
        let proposes = |actions: &[Action]| {
            actions.iter().any(
                |a| matches!(a, Action::BuildProposal { height, .. } if *height == BlockHeight::new(4)),
            )
        };

        let actions = state.on_qc_formed(&topology_schedule, block_3_hash, &qc, |_| {
            ProposalInputs::default()
        });
        assert!(!proposes(&actions), "the next block waits out the pace");
        assert!(actions.iter().any(|a| matches!(
            a,
            Action::SetTimer { id: TimerId::ProposalPace, duration } if *duration == SOLO_PROPOSAL_FLOOR
        )));

        state.set_time(formed_at.plus(SOLO_PROPOSAL_FLOOR));
        let actions = state.try_propose(&topology_schedule, |_| ProposalInputs::default());
        assert!(
            proposes(&actions),
            "the pace elapsed, so the block goes ahead"
        );
    }

    /// A quorum attached together to one replica trades its votes without
    /// crossing the network, so its QC paces the next proposal as a lone
    /// member's does. The same quorum spread over hosts proposes at once,
    /// and so does one whose block reached the host a pace ago.
    #[test]
    fn a_qc_formed_on_one_host_paces_the_next_proposal() {
        let formed_at = LocalTimestamp::from_millis(100_000);
        let qc_formed = |attached: &[u64], arrived: LocalTimestamp| {
            let (state, topology_schedule) = make_test_state_with_validators(3);
            let mut state = attached
                .iter()
                .fold(state, |state, &id| state.signed_by(ValidatorId::new(id)));
            state.set_time(formed_at);
            state.committed_height = BlockHeight::new(3);
            state.verification.on_block_persisted(BlockHeight::new(3));
            state.view_change.view = Round::new(3);
            let block_3 = make_header_at_height(BlockHeight::new(3), 99_000);
            let block_3_hash = block_3.hash();
            state.committed_hash = block_3_hash;
            state.pending_blocks.insert(PendingBlock::from_manifest(
                block_3,
                BlockManifest::default(),
                arrived,
            ));
            let mut signers = SignerBitfield::new(3);
            for index in 0..3 {
                signers.set(index);
            }
            // SAFETY: synthetic test fixture, no real signature.
            let qc = Verified::<QuorumCertificate>::new_unchecked_for_test(QuorumCertificate::new(
                block_3_hash,
                ShardId::ROOT,
                BlockHeight::new(3),
                BlockHash::from_raw(Hash::from_bytes(b"block_2")),
                Round::new(2),
                signers,
                AggregateSignature::ZERO,
                WeightedTimestamp::from_millis(100_000),
            ));
            state.on_qc_formed(&topology_schedule, block_3_hash, &qc, |_| {
                ProposalInputs::default()
            })
        };
        let proposes = |actions: &[Action]| {
            actions.iter().any(
                |a| matches!(a, Action::BuildProposal { height, .. } if *height == BlockHeight::new(4)),
            )
        };
        let paced = |actions: &[Action]| {
            actions.iter().any(|a| {
                matches!(
                    a,
                    Action::SetTimer {
                        id: TimerId::ProposalPace,
                        ..
                    }
                )
            })
        };

        let together = qc_formed(&[0, 1, 2], formed_at);
        assert!(
            !proposes(&together) && paced(&together),
            "a quorum on one host waits out the pace"
        );

        let apart = qc_formed(&[0], formed_at);
        assert!(
            proposes(&apart) && !paced(&apart),
            "a quorum across hosts proposes at once"
        );

        let waited = qc_formed(&[0, 1, 2], formed_at.minus(SOLO_PROPOSAL_FLOOR));
        assert!(
            proposes(&waited) && !paced(&waited),
            "a block that reached the host a pace ago has been waited out"
        );
    }

    #[test]
    fn qc_formed_adopts_its_own_aggregate_at_any_weighted_timestamp() {
        // The aggregator holds no bound on the QC it just built, and the
        // absence is the point. A vote's timestamp rides outside
        // `BlockVoteMessage`, so the value is whatever a voter put there;
        // what makes the aggregate trustworthy is that it is the MEDIAN of a
        // quorum's clamped readings, which for `k >= 2f + 1` is always an
        // honest voter's own clock. Bounding one's own median against one's
        // own clock only ever refuses because the local clock is the outlier,
        // and the refusal is not free: the vote set is already marked
        // `qc_built` and the certified block already attached, so the height
        // is stranded and its half-published certificate is served to peers
        // that must refuse it. The bound lives at the three ingress sites
        // that judge a QC somebody else built.
        let (mut state, topology_schedule) = make_test_state();
        let now = LocalTimestamp::from_millis(100_000);
        state.set_time(now);
        state.committed_height = BlockHeight::new(3);
        state.verification.on_block_persisted(BlockHeight::new(3));
        state.view_change.view = Round::new(4);
        let envelope_ms =
            u64::try_from((MAX_TIMESTAMP_DELAY + MAX_TIMESTAMP_RUSH).as_millis()).unwrap();

        // Block 3 is the committed tip and its header is in memory, so the
        // QC over it is adopted and the proposal extends it.
        let block_3 = make_header_at_height(BlockHeight::new(3), 99_000);
        let block_3_hash = block_3.hash();
        state.committed_hash = block_3_hash;
        state.pending_blocks.insert(PendingBlock::from_manifest(
            block_3,
            BlockManifest::default(),
            LocalTimestamp::ZERO,
        ));
        let base = make_test_qc(block_3_hash, BlockHeight::new(3));
        // SAFETY: synthetic test fixture, no real signature.
        let qc = Verified::<QuorumCertificate>::new_unchecked_for_test(QuorumCertificate::new(
            base.block_hash(),
            base.shard_id(),
            base.height(),
            BlockHash::from_raw(Hash::from_bytes(b"block_2")),
            base.round(),
            base.signers().clone(),
            base.aggregated_signature(),
            WeightedTimestamp::from_millis(now.as_millis() + envelope_ms + 1),
        ));

        let actions = state.on_qc_formed(&topology_schedule, block_3_hash, &qc, |_| {
            ProposalInputs::default()
        });
        assert!(
            actions
                .iter()
                .any(|a| matches!(a, Action::BuildProposal { .. })),
            "a locally formed QC must drive the next proposal: {actions:?}"
        );
    }

    #[test]
    fn test_two_chain_commit_defers_when_certified_uncached() {
        // Two-chain commit emits `BlockReadyToCommit { certified, source }`
        // where `certified` is the assembled `Verified<CertifiedBlock>` for
        // the committable block. The handle lives in the pipeline's
        // `verified_certified_blocks` map once per-root + state-root
        // assembly completes. If the cache entry is missing (e.g.
        // assembly is still in flight), we must defer — a later root
        // completion drives the deferred commit via
        // `drive_deferred_commit_for`.
        let (state, _topology) = make_test_state();

        let committable_hash = BlockHash::from_raw(Hash::from_bytes(b"parent"));
        let child_hash = BlockHash::from_raw(Hash::from_bytes(b"child"));
        let qc = Verified::<QuorumCertificate>::new_unchecked_for_test(QuorumCertificate::new(
            child_hash,
            ShardId::ROOT,
            BlockHeight::new(4),
            committable_hash,
            Round::new(0),
            SignerBitfield::empty(),
            AggregateSignature::ZERO,
            WeightedTimestamp::from_millis(100_000),
        ));

        // No verified certified cached — exercises the deferral path.
        let actions = state.try_two_chain_commit(&qc, CommitSource::Aggregator);
        assert!(
            actions.is_empty(),
            "expected no BlockReadyToCommit when certified uncached, got {actions:?}"
        );
    }

    #[test]
    fn test_deferred_proposal_suppresses_rebuild_until_unblocked() {
        // A deferred proposal (parent tree missing) must NOT re-emit
        // BuildProposal on every subsequent try_propose for the same
        // (height, round) — that's the spin loop v7 was hitting, producing
        // hundreds of `"Requesting block build for proposal"` log lines per
        // second while peers timed out on the proposer slot. After the
        // parent tree lands, `take_ready_proposal` must clear the gate so
        // the next try_propose can dispatch.

        let (mut state, topology_schedule) = make_test_state();
        state.set_time(LocalTimestamp::from_millis(100_000));

        // Local validator is ValidatorId::new(0). Rounds increase per block, so
        // point the chain at (h=4, r=4) where proposer = (4+4)%4 = ValidatorId::new(0).
        let parent_block_hash = BlockHash::from_raw(Hash::from_bytes(b"parent_tree_missing"));
        state.committed_height = BlockHeight::new(3);
        state.committed_hash = parent_block_hash;
        state.latest_qc = Some(make_test_qc(parent_block_hash, BlockHeight::new(3)));
        state.view_change.view = Round::new(4);
        // Intentionally do NOT call on_block_persisted — parent tree
        // unavailable forces the defer branch.

        let asked = Cell::new(false);
        let tx = admissible_at(100_000);
        let first = state.try_propose(&topology_schedule, offering(&asked, &tx));
        assert!(
            first
                .iter()
                .all(|a| !matches!(a, Action::BuildProposal { .. })),
            "first try_propose should have deferred, not dispatched"
        );
        assert!(
            state.proposal.deferred().is_some(),
            "defer slot should be recorded"
        );

        let second = state.try_propose(&topology_schedule, offering(&asked, &tx));
        assert!(
            second.is_empty(),
            "second try_propose for same (height, round) must be suppressed"
        );
        assert!(!asked.get(), "a deferred build asks for no content");

        // Parent tree lands — verification pipeline signals unblock and
        // take_ready_proposal clears the tracker's deferred slot.
        state.verification.on_block_persisted(BlockHeight::new(3));
        assert!(
            state.take_ready_proposal(),
            "take_ready_proposal should report unblocked"
        );
        assert!(
            state.proposal.deferred().is_none(),
            "deferred slot should be cleared"
        );

        let third = state.try_propose(&topology_schedule, offering(&asked, &tx));
        assert!(
            third.iter().any(
                |a| matches!(a, Action::BuildProposal { height, .. } if *height == BlockHeight::new(4))
            ),
            "third try_propose should dispatch the BuildProposal"
        );
        assert!(asked.get(), "the released build asks for its content");
        assert_eq!(
            proposed(&third),
            [tx.hash()],
            "and carries what it was offered"
        );
    }

    /// A proposal whose reshape substate walk cannot resolve must park and
    /// resume the moment the walk's inputs land — here a byte frontier
    /// lagging the committed tip, reconciled from storage on persistence.
    /// Nothing else re-drives it: the parked height is the one whose QC
    /// would advance the chain, so no commit, QC, or admission follows to
    /// latch a retry, and the round would otherwise burn its full
    /// view-change timeout on a fallback.
    #[test]
    fn substate_walk_park_resumes_the_proposal_when_the_frontier_reconciles() {
        let (mut state, _) = make_test_state();
        // The walk is inert with reshaping disabled, so arm the thresholds.
        let snapshot = TopologySchedule::single(Arc::new(
            make_test_state()
                .1
                .head()
                .as_ref()
                .clone()
                .with_params(NetworkParams {
                    reshape_thresholds: ReshapeThresholds {
                        split_bytes: 0,
                        split_fullness: u32::MAX,
                    },
                    ..NetworkParams::default()
                }),
        ));
        state.set_time(LocalTimestamp::from_millis(100_000));

        // Rounds increase per block, so (h=4, r=4) puts ValidatorId(0) — the
        // local validator — in the proposer slot.
        let parent_block_hash = BlockHash::from_raw(Hash::from_bytes(b"lagging_frontier"));
        state.committed_height = BlockHeight::new(3);
        state.committed_hash = parent_block_hash;
        state.latest_qc = Some(make_test_qc(parent_block_hash, BlockHeight::new(3)));
        state.view_change.view = Round::new(4);
        // The frontier still sits at genesis while the chain committed to 3 —
        // the sync-commit shape, whose commits carry no byte delta.
        assert_ne!(state.substate_bytes_frontier.0, state.committed_height);

        let asked = Cell::new(false);
        let tx = admissible_at(100_000);
        let first = state.try_propose(&snapshot, offering(&asked, &tx));
        assert!(
            first
                .iter()
                .all(|a| !matches!(a, Action::BuildProposal { .. })),
            "an unresolvable substate walk must park, not dispatch"
        );
        assert!(!asked.get(), "a parked build asks for no content");
        assert!(
            !state.take_ready_proposal(),
            "parking alone must not latch a retry"
        );

        // Persistence reconciles the frontier from storage.
        let _ = state.on_block_persisted(&snapshot, BlockHeight::new(3), 4_096, None);
        assert!(
            state.take_ready_proposal(),
            "the reconcile must latch a proposal retry"
        );

        let second = state.try_propose(&snapshot, offering(&asked, &tx));
        assert!(
            second.iter().any(
                |a| matches!(a, Action::BuildProposal { height, .. } if *height == BlockHeight::new(4))
            ),
            "the retry must dispatch the BuildProposal the park was holding"
        );
        assert!(asked.get(), "the released build asks for its content");
        assert_eq!(
            proposed(&second),
            [tx.hash()],
            "and carries what it was offered"
        );
    }

    #[test]
    #[allow(clippy::too_many_lines)] // straight-line sequence; splitting hurts readability
    fn test_qc_verification_caching_skips_redundant_verification() {
        // When the same parent QC appears in multiple block headers (e.g. after a
        // view change), we verify it once and hit the cache for subsequent blocks.

        let (mut state, topology_schedule) = make_multi_validator_state_at(0);
        state.set_time(LocalTimestamp::from_millis(100_000));

        let parent_block_hash = BlockHash::from_raw(Hash::from_bytes(b"parent_block"));
        state.committed_height = BlockHeight::new(1);
        state.committed_hash = parent_block_hash;

        let mut signers = SignerBitfield::new(4);
        signers.set(0);
        signers.set(1);
        signers.set(2);
        let parent_qc = {
            let __qc = make_test_qc(parent_block_hash, BlockHeight::new(1));
            QuorumCertificate::new(
                __qc.block_hash(),
                __qc.shard_id(),
                __qc.height(),
                __qc.parent_block_hash(),
                __qc.round(),
                signers,
                __qc.aggregated_signature(),
                WeightedTimestamp::from_millis(99_000),
            )
        };

        let header1 = {
            let __h = make_header_at_height(BlockHeight::new(2), 100_000);
            BlockHeader::new(BlockHeaderParts {
                shard_id: __h.shard_id(),
                height: __h.height(),
                parent_block_hash,
                parent_qc: parent_qc.clone().into(),
                proposer: __h.proposer(),
                timestamp: __h.timestamp(),
                round: __h.round(),
                is_fallback: __h.is_fallback(),
                state_root: __h.state_root(),
                body_root: __h.body_root(),
                provision_tx_roots: __h.provision_tx_roots().clone(),
                txs_in_flight: __h.txs_in_flight(),
                load: __h.load(),
                ..Default::default()
            })
        };
        let actions1 = state.on_block_header(
            &topology_schedule,
            &header1,
            BlockManifest::default(),
            |_| None,
            |_| None,
            |_| None,
        );
        assert!(
            actions1
                .iter()
                .any(|a| matches!(a, Action::VerifyQcSignature { .. })),
            "first block must trigger QC verification"
        );

        // Simulate verification success; same path as on_qc_signature_verified(valid=true).
        // SAFETY: synthetic test fixture, no real signature.
        state.verification.cache_verified_qc(
            Verified::<QuorumCertificate>::new_unchecked_for_test(parent_qc.clone()),
        );

        // Second block at round 1 sharing the same parent QC.
        let header2 = {
            let __h = make_header_at_height(BlockHeight::new(2), 100_001);
            BlockHeader::new(BlockHeaderParts {
                shard_id: __h.shard_id(),
                height: __h.height(),
                parent_block_hash,
                parent_qc: parent_qc.into(),
                proposer: ValidatorId::new(3),
                timestamp: __h.timestamp(),
                round: Round::new(1),
                is_fallback: __h.is_fallback(),
                state_root: __h.state_root(),
                body_root: __h.body_root(),
                provision_tx_roots: __h.provision_tx_roots().clone(),
                txs_in_flight: __h.txs_in_flight(),
                load: __h.load(),
                ..Default::default()
            })
        };
        let actions2 = state.on_block_header(
            &topology_schedule,
            &header2,
            BlockManifest::default(),
            |_| None,
            |_| None,
            |_| None,
        );
        assert!(
            !actions2
                .iter()
                .any(|a| matches!(a, Action::VerifyQcSignature { .. })),
            "second block must reuse cached verification"
        );
    }

    #[test]
    fn qc_cache_hit_requires_byte_equal_qc_not_just_block_hash() {
        // A Byzantine peer who sees a legitimately-cached `block_hash` must
        // not be able to ship a header whose parent_qc reuses that block_hash
        // with fabricated `signers` / `round` / `parent_block_hash` and have
        // those forged fields adopted into `latest_qc` without re-verification.

        let (mut state, topology_schedule) = make_multi_validator_state_at(0);
        state.set_time(LocalTimestamp::from_millis(100_000));

        let parent_block_hash = BlockHash::from_raw(Hash::from_bytes(b"parent_block"));
        state.committed_height = BlockHeight::new(1);
        state.committed_hash = parent_block_hash;

        let mut signers = SignerBitfield::new(4);
        signers.set(0);
        signers.set(1);
        signers.set(2);
        let honest_qc = {
            let __qc = make_test_qc(parent_block_hash, BlockHeight::new(1));
            QuorumCertificate::new(
                __qc.block_hash(),
                __qc.shard_id(),
                __qc.height(),
                __qc.parent_block_hash(),
                __qc.round(),
                signers.clone(),
                __qc.aggregated_signature(),
                WeightedTimestamp::from_millis(99_000),
            )
        };

        // Cache the honest QC as if it had been verified.
        // SAFETY: synthetic test fixture, no real signature.
        state.verification.cache_verified_qc(
            Verified::<QuorumCertificate>::new_unchecked_for_test(honest_qc.clone()),
        );

        // Byzantine header reuses the honest QC's block_hash + signers + height
        // (so `validate_header`'s quorum-power and structural checks still pass)
        // but mutates fields outside the cache key, e.g. the weighted timestamp —
        // the cache must bind every signed field, otherwise a hit would skip
        // re-verifying a forged signature. The forged timestamp stays within the
        // clock envelope so this isolates the cache-binding check rather than the
        // far-future parent-QC timestamp bound.
        let forged_qc = {
            let __qc = honest_qc;
            QuorumCertificate::new(
                __qc.block_hash(),
                __qc.shard_id(),
                __qc.height(),
                __qc.parent_block_hash(),
                __qc.round(),
                __qc.signers().clone(),
                __qc.aggregated_signature(),
                WeightedTimestamp::from_millis(101_000),
            )
        };
        let forged_header = {
            let __h = make_header_at_height(BlockHeight::new(2), 100_000);
            BlockHeader::new(BlockHeaderParts {
                shard_id: __h.shard_id(),
                height: __h.height(),
                parent_block_hash,
                parent_qc: forged_qc.into(),
                proposer: __h.proposer(),
                timestamp: __h.timestamp(),
                round: __h.round(),
                is_fallback: __h.is_fallback(),
                state_root: __h.state_root(),
                body_root: __h.body_root(),
                provision_tx_roots: __h.provision_tx_roots().clone(),
                txs_in_flight: __h.txs_in_flight(),
                load: __h.load(),
                ..Default::default()
            })
        };

        let actions = state.on_block_header(
            &topology_schedule,
            &forged_header,
            BlockManifest::default(),
            |_| None,
            |_| None,
            |_| None,
        );

        // The forged QC must trigger signature verification rather than being
        // accepted as a cache hit.
        assert!(
            actions
                .iter()
                .any(|a| matches!(a, Action::VerifyQcSignature { .. })),
            "forged QC reusing cached block_hash must still trigger signature verification"
        );

        // And `latest_qc` must not have been mutated to reflect the forged
        // weighted_timestamp on the cache-hit path.
        assert!(
            state.latest_qc.as_ref().is_none_or(
                |qc| qc.weighted_timestamp() != forged_header.parent_qc().weighted_timestamp()
            ),
            "forged QC must not be adopted as latest_qc on cache hit"
        );
    }

