    #[test]
    fn test_syncing_validator_proposes_empty_block() {
        let (mut state, topology_schedule) = make_test_state();
        state.set_time(LocalTimestamp::from_millis(100_000));
        // Simulate committed state so parent tree is available for BuildProposal.
        state.committed_height = BlockHeight::new(3);
        state.verification.on_block_persisted(BlockHeight::new(3));

        // Validator 0 proposes for height 4 since (4+0)%4 = 0.
        state.latest_qc = Some({
            let __qc = make_test_qc(
                BlockHash::from_raw(Hash::from_bytes(b"block_3")),
                BlockHeight::new(3),
            );
            // SAFETY: synthetic test fixture, no real signature.
            Verified::<QuorumCertificate>::new_unchecked_for_test(QuorumCertificate::new(
                __qc.block_hash(),
                __qc.shard_id(),
                __qc.height(),
                BlockHash::from_raw(Hash::from_bytes(b"block_2")),
                __qc.round(),
                __qc.signers().clone(),
                __qc.aggregated_signature(),
                __qc.weighted_timestamp(),
            ))
        });
        // The QC's block is the committed tip in this fixture; naming it
        // keeps the parent resolvable, as it always is on a live chain.
        state.committed_hash = state.latest_qc.as_ref().unwrap().block_hash();

        // Rounds increase per block: height 4 proposes at round 4
        // (proposer_for(4, 4) = validator 0).
        state.view_change.view = Round::new(4);
        state.set_block_syncing(true);
        assert!(state.is_block_syncing());

        // Ready txs must be dropped — sync blocks are always empty.
        let ready_txs = vec![Arc::new(test_utils::verified_test_transaction(1))];
        let actions = state.try_propose(&topology_schedule, |_| ProposalInputs {
            ready_txs,
            ..ProposalInputs::default()
        });

        let proposal = actions
            .iter()
            .find(|a| matches!(a, Action::BuildProposal { .. }))
            .expect("sync block should still produce BuildProposal");
        let Action::BuildProposal {
            is_fallback,
            transactions,
            finalizations,
            ..
        } = proposal
        else {
            unreachable!()
        };
        assert!(!is_fallback);
        assert!(transactions.is_empty());
        assert!(finalizations.is_empty());
    }

    #[test]
    fn test_syncing_validator_uses_current_timestamp() {
        // Sync blocks timestamp with the wall clock; they do not inherit the
        // parent's weighted timestamp like fallback blocks do.
        let (mut state, topology_schedule) = make_test_state();
        let current_time = LocalTimestamp::from_millis(12_345_000);
        state.set_time(current_time);
        state.committed_height = BlockHeight::new(3);
        state.verification.on_block_persisted(BlockHeight::new(3));

        let old_timestamp = 1000u64;
        state.latest_qc = Some({
            let __qc = make_test_qc(
                BlockHash::from_raw(Hash::from_bytes(b"block_3")),
                BlockHeight::new(3),
            );
            // SAFETY: synthetic test fixture, no real signature.
            Verified::<QuorumCertificate>::new_unchecked_for_test(QuorumCertificate::new(
                __qc.block_hash(),
                __qc.shard_id(),
                __qc.height(),
                BlockHash::from_raw(Hash::from_bytes(b"block_2")),
                __qc.round(),
                __qc.signers().clone(),
                __qc.aggregated_signature(),
                WeightedTimestamp::from_millis(old_timestamp),
            ))
        });
        // The QC's block is the committed tip in this fixture; naming it
        // keeps the parent resolvable, as it always is on a live chain.
        state.committed_hash = state.latest_qc.as_ref().unwrap().block_hash();
        // Height 4 proposes at round 4 (rounds increase per block).
        state.view_change.view = Round::new(4);
        state.set_block_syncing(true);

        let actions = state.try_propose(&topology_schedule, |_| ProposalInputs::default());
        let Some(Action::BuildProposal { timestamp, .. }) = actions
            .iter()
            .find(|a| matches!(a, Action::BuildProposal { .. }))
        else {
            panic!("expected BuildProposal");
        };
        assert_eq!(*timestamp, ProposerTimestamp::from_local(current_time));
        assert_ne!(timestamp.as_millis(), old_timestamp);
    }

    #[test]
    fn second_propose_after_self_vote_is_suppressed() {
        // Once a proposal's build completes and the proposer self-votes it,
        // a retry at the still-current view (routinely queued by
        // TransactionsAdmitted / ProvisionsAdmitted) must not build a sibling
        // block — that would sign two votes at one round.
        let (mut state, topology_schedule) = make_test_state();
        state.set_time(LocalTimestamp::from_millis(100_000));
        state.committed_height = BlockHeight::new(3);
        state.verification.on_block_persisted(BlockHeight::new(3));
        state.latest_qc = Some(make_test_qc(
            BlockHash::from_raw(Hash::from_bytes(b"block_3")),
            BlockHeight::new(3),
        ));
        // The QC's block is the committed tip in this fixture; naming it
        // keeps the parent resolvable, as it always is on a live chain.
        state.committed_hash = state.latest_qc.as_ref().unwrap().block_hash();
        // Height 4 proposes at round 4 (rounds increase per block).
        state.view_change.view = Round::new(4);

        let height = BlockHeight::new(4);
        let round = Round::new(4);
        let actions = state.try_propose(&topology_schedule, |_| ProposalInputs::default());
        assert!(
            actions
                .iter()
                .any(|a| matches!(a, Action::BuildProposal { .. })),
            "first proposal should build"
        );

        // The runner completes the build: the tracker slot clears and the
        // proposer self-votes, consuming the round.
        assert!(matches!(
            state.proposal.take_matching(height, round),
            TakeResult::Matched
        ));
        let block_hash = BlockHash::from_raw(Hash::from_bytes(b"own_block_4"));
        let vote = state.create_vote(
            &topology_schedule,
            state.sole_signer(),
            block_hash,
            height,
            round,
        );
        assert!(
            vote.iter()
                .any(|a| matches!(a, Action::SignAndBroadcastBlockVote { .. }))
        );
        assert_eq!(state.sole().last_voted_round, round);

        // The retry at the same view must be a no-op, not a sibling build.
        let retry = state.try_propose(&topology_schedule, |_| ProposalInputs::default());
        assert!(retry.is_empty(), "retry built a sibling: {retry:?}");
    }

    #[test]
    fn build_proposal_classifies_against_the_anchored_committee_not_the_head() {
        // The proposed block anchors at its `parent_qc` weighted timestamp
        // (epoch 0, where ROOT is one shard). The schedule's head has
        // already flipped to the post-split window (two shards). The
        // verifier recomputes `ticks`/`provision_tx_roots` against the
        // anchored window, so the proposer must classify against it too —
        // never the flipped head — or every replica rejects the header.
        let (mut state, _) = make_test_state();
        state.set_time(LocalTimestamp::from_millis(100_000));
        let parent = BlockHash::from_raw(Hash::from_bytes(b"block_3"));
        state.committed_height = BlockHeight::new(3);
        state.committed_hash = parent;
        state.committed_block_anchor_wt = WeightedTimestamp::from_millis(500);
        state.verification.on_block_persisted(BlockHeight::new(3));
        state.latest_qc = Some({
            let __qc = make_test_qc(parent, BlockHeight::new(3));
            // SAFETY: synthetic test fixture, no real signature. Anchored at
            // epoch 0 (wt 500 with a 1000 ms epoch).
            Verified::<QuorumCertificate>::new_unchecked_for_test(QuorumCertificate::new(
                __qc.block_hash(),
                __qc.shard_id(),
                __qc.height(),
                BlockHash::ZERO,
                __qc.round(),
                __qc.signers().clone(),
                __qc.aggregated_signature(),
                WeightedTimestamp::from_millis(500),
            ))
        });
        state.view_change.view = Round::new(4);

        // Epoch 0 carries ROOT (one shard) — the proposal's anchor; epoch 1
        // splits it (two shards) and is installed as the flipped head.
        let keys: Vec<BlsSigner> = (0..4).map(|_| BlsSigner::generate()).collect();
        let validators: Vec<ValidatorInfo> = keys
            .iter()
            .enumerate()
            .map(|(i, k)| ValidatorInfo {
                validator_id: ValidatorId::new(i as u64),
                public_key: k.public_key(),
            })
            .collect();
        let pre_split = Arc::new(TopologySnapshot::new(
            NetworkDefinition::simulator(),
            1,
            ValidatorSet::new(validators.clone()),
        ));
        let post_split = Arc::new(TopologySnapshot::new(
            NetworkDefinition::simulator(),
            2,
            ValidatorSet::new(validators),
        ));
        let mut sched = TopologySchedule::new(
            EpochWindows::new(0, 1000),
            Epoch::new(0),
            Arc::clone(&pre_split),
        );
        sched.insert(Epoch::new(1), Arc::clone(&post_split));
        sched.set_head(post_split);

        let actions = state.try_propose(&sched, |_| ProposalInputs::default());
        let classification = actions
            .iter()
            .find_map(|a| match a {
                Action::BuildProposal {
                    classification_topology_snapshot: classification_topology,
                    ..
                } => Some(classification_topology),
                _ => None,
            })
            .expect("a BuildProposal must dispatch");
        assert_eq!(
            classification.num_shards(),
            1,
            "classification anchors at the parent_qc window (ROOT, pre-split), not the two-shard head",
        );
    }

    #[test]
    fn test_sync_complete_exits_sync_mode() {
        let (mut state, topology_schedule) = make_test_state();
        state.set_block_syncing(true);
        assert!(state.is_block_syncing());

        // Fresh state has no pending blocks and is already in the
        // consensus subset, so on_sync_complete returns no actions — the
        // remote-header / provision flushes happen in NodeStateMachine's
        // BlockSyncComplete arm.
        let actions = state.on_block_sync_complete(&topology_schedule);
        assert!(!state.is_block_syncing());
        assert!(actions.is_empty());
    }

    /// A 4-member committee where validator 0 (the local node) is a
    /// full member but outside the consensus subset — placed, not yet
    /// ready.
    fn not_ready_member_topology() -> TopologySchedule {
        use std::collections::{BTreeMap, HashMap};

        let validators: Vec<ValidatorInfo> = (0..4)
            .map(|i| ValidatorInfo {
                validator_id: ValidatorId::new(i),
                public_key: BlsSigner::generate().public_key(),
            })
            .collect();
        let vs = ValidatorSet::new(validators);
        let members: Vec<ValidatorId> = (0..4).map(ValidatorId::new).collect();
        let mut committees = HashMap::new();
        committees.insert(ShardId::ROOT, members.clone());
        let mut consensus = HashMap::new();
        consensus.insert(ShardId::ROOT, members[1..].to_vec());
        let snapshot = TopologySnapshot::from_explicit_committees(
            NetworkDefinition::simulator(),
            &vs,
            committees,
            consensus,
            BTreeMap::new(),
            HashMap::new(),
            BTreeMap::new(),
            BTreeMap::new(),
            BTreeMap::new(),
            BTreeSet::new(),
        );
        TopologySchedule::single(Arc::new(snapshot))
    }

    /// A committee member outside the consensus subset — placed but not
    /// yet ready — emits exactly one `SignAndBroadcastReadySignal` when
    /// sync reaches the tip, windowed from the next committable height
    /// and addressed to every other committee member. (The already-ready
    /// case stays silent: `test_sync_complete_exits_sync_mode`.)
    #[test]
    fn sync_complete_emits_ready_signal_when_not_in_consensus_subset() {
        use std::collections::{BTreeMap, HashMap};

        let (mut state, _) = make_test_state();
        let validators: Vec<ValidatorInfo> = (0..4)
            .map(|i| ValidatorInfo {
                validator_id: ValidatorId::new(i),
                public_key: BlsSigner::generate().public_key(),
            })
            .collect();
        let vs = ValidatorSet::new(validators);
        let members: Vec<ValidatorId> = (0..4).map(ValidatorId::new).collect();
        let mut committees = HashMap::new();
        committees.insert(ShardId::ROOT, members.clone());
        // Validator 0 (the local node) is a member but not ready.
        let mut consensus = HashMap::new();
        consensus.insert(ShardId::ROOT, members[1..].to_vec());
        let snapshot = TopologySnapshot::from_explicit_committees(
            NetworkDefinition::simulator(),
            &vs,
            committees,
            consensus,
            BTreeMap::new(),
            HashMap::new(),
            BTreeMap::new(),
            BTreeMap::new(),
            BTreeMap::new(),
            BTreeSet::new(),
        );
        let topology_schedule = TopologySchedule::single(Arc::new(snapshot));

        state.set_block_syncing(true);
        let actions = state.on_block_sync_complete(&topology_schedule);
        assert!(!state.is_block_syncing());

        let signals: Vec<_> = actions
            .iter()
            .filter_map(|a| match a {
                Action::SignAndBroadcastReadySignal {
                    wt_window_start,
                    wt_window_end,
                    recipients,
                    ..
                } => Some((wt_window_start, wt_window_end, recipients)),
                _ => None,
            })
            .collect();
        let [(start, end, recipients)] = signals.as_slice() else {
            panic!("expected exactly one ready signal, got {actions:?}");
        };
        assert_eq!(**start, state.clock.now());
        assert_eq!(
            **end,
            start.plus(ready_signal_window(topology_schedule.epoch_duration_ms()))
        );
        assert_eq!(recipients.len(), 3);
        assert!(!recipients.contains(&state.sole_signer()));
    }

    /// A replica that finished bootstrap sync before its committee window
    /// opened missed the sync-complete emission (the head committee
    /// didn't include it yet). The beacon commit that activates the
    /// window must re-fire the signal — without this the flag only
    /// flips via the ready timeout.
    #[test]
    fn beacon_commit_re_fires_ready_signal_for_synced_not_ready_member() {
        let (mut state, _) = make_test_state();
        let topology_schedule = not_ready_member_topology();

        let actions = state.on_beacon_block_persisted(&topology_schedule);
        let signals = actions
            .iter()
            .filter(|a| matches!(a, Action::SignAndBroadcastReadySignal { .. }))
            .count();
        assert_eq!(
            signals, 1,
            "expected exactly one re-fired ready signal, got {actions:?}"
        );

        // Mid-sync the re-kick stays quiet: the height window would be
        // stale, and sync completion re-fires the emission itself.
        state.set_block_syncing(true);
        let actions = state.on_beacon_block_persisted(&topology_schedule);
        assert!(
            actions.is_empty(),
            "no ready signal while block sync is in flight, got {actions:?}"
        );
    }

    /// An already-ready member (in the consensus subset) stays silent on
    /// beacon commits — the re-kick is only for the placed-but-not-ready
    /// window.
    #[test]
    fn beacon_commit_emits_no_ready_signal_for_consensus_member() {
        let (mut state, topology_schedule) = make_test_state();
        let actions = state.on_beacon_block_persisted(&topology_schedule);
        assert!(actions.is_empty(), "expected no actions, got {actions:?}");
    }

    #[test]
    fn beacon_behind_synced_block_re_buffers_until_epoch_adoption() {
        // A synced block whose committee epoch the beacon hasn't committed
        // yet must survive the lookup miss: it returns to the buffer and the
        // beacon adopting the epoch replays it into QC verification.
        // Discarding it would leave a hole the drain could never refill
        // without a network re-fetch.
        const ED: u64 = 1_000;
        let epoch0 = Arc::new(committee_snapshot_with_ids(&[0, 1, 2, 3]));
        let mut schedule = TopologySchedule::new(EpochWindows::new(0, ED), Epoch::new(0), epoch0);

        let mut state = ShardCoordinator::new(
            Arc::new(BlsVerifier),
            ShardId::ROOT,
            ShardConsensusConfig::default(),
            RecoveredState::default(),
            WeightedTimestamp::ZERO,
        )
        .signed_by(ValidatorId::new(0));
        state.set_time(LocalTimestamp::from_millis(100_000));
        state.committed_height = BlockHeight::new(3);
        state.committed_hash = BlockHash::from_raw(Hash::from_bytes(b"anchor_parent"));
        // The block's committee anchors on its parent, the committed tip,
        // whose anchor sits in epoch 5 — above the schedule head.
        state.committed_block_anchor_wt = WeightedTimestamp::from_millis(5 * ED);
        state.set_block_syncing(true);

        let block = block_with_parent_qc_ts(BlockHeight::new(4), 5 * ED);
        let block_hash = block.hash();
        let mut signers = SignerBitfield::new(4);
        signers.set(0);
        signers.set(1);
        signers.set(2);
        let qc = QuorumCertificate::new(
            block_hash,
            ShardId::ROOT,
            BlockHeight::new(4),
            block.header().parent_block_hash(),
            block.header().round(),
            signers,
            AggregateSignature::ZERO,
            WeightedTimestamp::from_millis(5 * ED),
        );
        let certified = CertifiedBlock::new_unchecked(block, qc);

        let actions = state.on_sync_block_ready_to_apply(&schedule, certified);
        assert!(
            actions.is_empty(),
            "beacon-behind defer emits nothing: {actions:?}"
        );
        assert!(
            state
                .block_sync
                .has_buffered(BlockHeight::new(4), &block_hash)
        );

        // Beacon adopts the epoch: the parked block replays into verification.
        schedule.insert(
            Epoch::new(5),
            Arc::new(committee_snapshot_with_ids(&[0, 1, 2, 3])),
        );
        let actions = state.on_beacon_block_persisted(&schedule);
        assert!(
            actions
                .iter()
                .any(|a| matches!(a, Action::VerifyQcSignature { .. })),
            "expected VerifyQcSignature after epoch adoption; got {actions:?}"
        );
        assert!(
            !state
                .block_sync
                .has_buffered(BlockHeight::new(4), &block_hash)
        );
    }

    #[test]
    fn beacon_witness_parked_on_beacon_lag_retries_on_epoch_adoption() {
        // A block whose committee epoch this node's beacon hasn't committed
        // yet must survive the committee lookup miss: its beacon-witness
        // verification parks and replays when the beacon adopts the epoch.
        // Dropping it strands the block at `NOT_STARTED` — no shard event can
        // revive it — so the shard wedges on a view-change loop.
        const ED: u64 = 1_000;
        let epoch0 = Arc::new(committee_snapshot_with_ids(&[0, 1, 2, 3]));
        let mut schedule = TopologySchedule::new(EpochWindows::new(0, ED), Epoch::new(0), epoch0);

        let mut state = ShardCoordinator::new(
            Arc::new(BlsVerifier),
            ShardId::ROOT,
            ShardConsensusConfig::default(),
            RecoveredState::default(),
            WeightedTimestamp::ZERO,
        )
        .signed_by(ValidatorId::new(0));
        state.committed_height = BlockHeight::new(3);
        // The block's parent is the committed tip, so the witness-leaf walk
        // terminates immediately and verification can dispatch the moment the
        // committee resolves.
        state.committed_hash = BlockHash::from_raw(Hash::from_bytes(b"anchor_parent"));
        // The block's committee anchors on its parent, so it is the parent's
        // anchor that has to sit above the schedule head for the committee to
        // be unresolvable.
        state.committed_block_anchor_wt = WeightedTimestamp::from_millis(5 * ED);

        // Parent QC weighted timestamp in epoch 5 — above the schedule head,
        // so the block's committee is unresolvable until the beacon catches up.
        let block = block_with_parent_qc_ts(BlockHeight::new(4), 5 * ED);
        let block_hash = block.hash();
        install_complete_block(&mut state, &block);

        // Park exactly as the beacon-behind retry path does on a committee miss.
        state
            .verification
            .park_beacon_witness_awaiting_committee(block_hash);

        // Beacon still behind epoch 5: the block re-parks, nothing dispatches.
        let actions = state.on_beacon_block_persisted(&schedule);
        assert!(
            !actions
                .iter()
                .any(|a| matches!(a, Action::VerifyBeaconWitnessRoot { .. })),
            "a still-behind beacon must not dispatch: {actions:?}"
        );

        // Beacon adopts epoch 5: the parked verification replays.
        schedule.insert(
            Epoch::new(5),
            Arc::new(committee_snapshot_with_ids(&[0, 1, 2, 3])),
        );
        let actions = state.on_beacon_block_persisted(&schedule);
        assert!(
            actions
                .iter()
                .any(|a| matches!(a, Action::VerifyBeaconWitnessRoot { .. })),
            "epoch adoption must replay the parked beacon-witness verification; got {actions:?}"
        );
    }

    #[test]
    fn already_applied_delivery_emits_nothing() {
        // A refetch that overlapped the height's `SyncBlockApplied` dedups
        // away. Completion is the FSM's call, so the shard neither resumes
        // nor re-dispatches on the duplicate.
        let (mut state, topology_schedule) = make_test_state();
        state.set_time(LocalTimestamp::from_millis(100_000));
        state.committed_height = BlockHeight::new(3);

        // Height 4 admitted to chain state, its commit waiting on a
        // round-contiguous child that live consensus has yet to certify.
        let block = block_with_parent_qc_ts(BlockHeight::new(4), 100);
        let block_hash = block.hash();
        state
            .block_sync
            .mark_applied(BlockHeight::new(4), block_hash);

        state.set_block_syncing(true);

        let mut signers = SignerBitfield::new(4);
        signers.set(0);
        signers.set(1);
        signers.set(2);
        let qc = QuorumCertificate::new(
            block_hash,
            ShardId::ROOT,
            BlockHeight::new(4),
            block.header().parent_block_hash(),
            block.header().round(),
            signers,
            AggregateSignature::ZERO,
            WeightedTimestamp::from_millis(100),
        );
        let actions = state.on_sync_block_ready_to_apply(
            &topology_schedule,
            CertifiedBlock::new_unchecked(block, qc),
        );

        assert!(actions.is_empty(), "got {actions:?}");
        assert!(
            state.is_block_syncing(),
            "the shard leaves sync mode on BlockSyncComplete, not on a duplicate"
        );
    }

    #[test]
    fn apply_synced_block_emits_sync_block_applied() {
        // Every applied block tells the FSM, which holds the height out of
        // its window and reads completion off it.
        let (mut state, topology_schedule) = make_test_state();
        state.set_time(LocalTimestamp::from_millis(100_000));
        state.committed_height = BlockHeight::new(3);
        state.committed_hash = BlockHash::from_raw(Hash::from_bytes(b"anchor_parent"));
        state.set_block_syncing(true);

        let block = block_with_parent_qc_ts(BlockHeight::new(4), 100);
        let block_hash = block.hash();
        let mut signers = SignerBitfield::new(4);
        signers.set(0);
        signers.set(1);
        signers.set(2);
        let qc = QuorumCertificate::new(
            block_hash,
            ShardId::ROOT,
            BlockHeight::new(4),
            block.header().parent_block_hash(),
            block.header().round(),
            signers,
            AggregateSignature::ZERO,
            WeightedTimestamp::from_millis(100),
        );
        let actions = state.on_sync_block_ready_to_apply(
            &topology_schedule,
            CertifiedBlock::new_unchecked(block, qc),
        );
        assert!(
            actions
                .iter()
                .any(|a| matches!(a, Action::VerifyQcSignature { .. }))
        );
        let qc = make_test_qc(block_hash, BlockHeight::new(4));
        let actions = state.on_qc_signature_verified(
            &topology_schedule,
            QcSubject::SyncedBlock(block_hash),
            Ok(qc),
        );
        assert!(
            actions.iter().any(|a| matches!(
                a,
                Action::SyncBlockApplied { height } if *height == BlockHeight::new(4)
            )),
            "got {actions:?}"
        );
        assert!(
            actions.iter().any(|a| matches!(
                a,
                Action::AttachCertifiedUncommitted { certified }
                    if certified.block().hash() == block_hash
            )),
            "an applied block is servable before it commits: {actions:?}"
        );
        assert!(
            state.is_block_syncing(),
            "the shard does not decide completion on its own"
        );
    }

    /// A synced block whose QC verifies while the height below it is
    /// still pending sits above the frontier. When consensus then commits
    /// that lower height on its own, the commit raises the frontier to the
    /// synced block, and the commit is what applies it: a refetch of the
    /// height finds the block already tracked and drops, so nothing else
    /// ever does.
    #[test]
    fn a_consensus_commit_applies_the_verified_synced_block_above_it() {
        let (mut state, schedule) = make_test_state();
        state.set_time(LocalTimestamp::from_millis(100_000));
        let from = BlockHash::from_raw(Hash::from_bytes(b"synced above tip"));
        state.committed_height = BlockHeight::GENESIS;
        state.committed_hash = from;
        state.committed_block_anchor_wt = WeightedTimestamp::from_millis(500);
        state.set_block_syncing(true);
        let k1 = block_chained_on(BlockHeight::new(1), from, 1_500);
        let k2 = block_chained_on(BlockHeight::new(2), k1.hash(), 1_700);
        let wire = |block: &Block| {
            let mut signers = SignerBitfield::new(4);
            signers.set(0);
            signers.set(1);
            signers.set(2);
            CertifiedBlock::new_unchecked(
                block.clone(),
                QuorumCertificate::new(
                    block.hash(),
                    ShardId::ROOT,
                    block.height(),
                    block.header().parent_block_hash(),
                    block.header().round(),
                    signers,
                    AggregateSignature::ZERO,
                    WeightedTimestamp::from_millis(2_000),
                ),
            )
        };
        let applied = |actions: &[Action], height: u64| {
            actions.iter().any(|action| {
                matches!(
                    action,
                    Action::SyncBlockApplied { height: h } if *h == BlockHeight::new(height)
                )
            })
        };

        let _ = state.on_sync_block_ready_to_apply(&schedule, wire(&k1));
        let _ = state.on_sync_block_ready_to_apply(&schedule, wire(&k2));
        let early = state.on_qc_signature_verified(
            &schedule,
            QcSubject::SyncedBlock(k2.hash()),
            Ok(make_test_qc(k2.hash(), k2.height())),
        );
        assert!(!applied(&early, 2), "K+1 waits above the frontier");

        let certified = Arc::new(Verified::new_unchecked_for_test(
            CertifiedBlock::new_unchecked(k1.clone(), make_test_qc(k1.hash(), k1.height())),
        ));
        let commit = state.on_block_ready_to_commit(&schedule, certified, CommitSource::Aggregator);
        assert_eq!(state.committed_height, BlockHeight::new(1));
        assert!(applied(&commit, 2), "got {commit:?}");
    }

    #[test]
    fn a_block_whose_parent_another_quorum_certified_still_lands_its_handle() {
        // A block can be certified by more than one quorum, and the verified
        // QC cache holds one certificate per block. When it holds another
        // quorum's certificate for the parent than the one this header
        // embeds, local assembly cannot link the header, yet the block's own
        // QC still attests it: without the handle no replica commits the
        // block or serves it to sync.
        let (mut state, _schedule) = make_test_state();
        let parent = BlockHash::from_raw(Hash::from_bytes(b"twice certified parent"));
        let block = block_chained_on(BlockHeight::new(2), parent, 1_500);
        let mut signers = SignerBitfield::new(4);
        signers.set(1);
        signers.set(2);
        signers.set(3);
        let other_quorum = QuorumCertificate::new(
            parent,
            ShardId::ROOT,
            BlockHeight::new(1),
            BlockHash::ZERO,
            Round::new(0),
            signers,
            AggregateSignature::ZERO,
            WeightedTimestamp::from_millis(1_600),
        );
        assert_ne!(&other_quorum, block.header().parent_qc());
        state
            .verification
            .cache_verified_qc(Verified::new_unchecked_for_test(other_quorum));
        for kind in state.verification.outstanding(&block) {
            state.verification.checked(block.hash(), kind);
        }

        install_complete_block(&mut state, &block);

        let actions = state.populate_certified_for(&make_test_qc(block.hash(), block.height()));

        assert!(
            actions
                .iter()
                .any(|a| matches!(a, Action::AttachCertifiedUncommitted { .. })),
            "got {actions:?}"
        );
        assert!(
            state
                .verification
                .cached_verified_certified_block(block.hash())
                .is_some()
        );
    }

    /// A QC signs the header alone. A proposer that hands this replica the
    /// certified header beside a body of its own making — one built to
    /// fail a pre-vote check, so the body root is never verified here —
    /// must not see that body certified when the quorum's QC lands: the
    /// replica drops it and syncs the body the header commits.
    #[test]
    fn a_certified_header_beside_a_forged_body_is_not_certified() {
        let (mut state, schedule) = make_test_state();
        let parent = BlockHash::from_raw(Hash::from_bytes(b"forged body parent"));
        let genuine = block_chained_on(BlockHeight::new(2), parent, 1_500);
        let Block::Live {
            header,
            transactions,
            certificates,
            provisions,
            abandonment_records,
            state_claims,
            terms,
            witness_sources,
            ..
        } = genuine.clone()
        else {
            unreachable!("the fixture builds a live block");
        };
        let forged = Block::Live {
            header,
            transactions,
            certificates,
            provisions,
            abandonment_records,
            state_claims,
            tick_manifest: Arc::new(Capped::from_array([TickLine::Discard {
                tick: TickId::new(ShardId::ROOT, BlockHeight::new(1)),
                cause: DiscardCause::Recovery,
            }])),
            terms,
            witness_sources,
        };
        let block_hash = genuine.hash();
        assert_eq!(forged.hash(), block_hash, "the header is the genuine one");
        let qc = make_test_qc(block_hash, genuine.height());

        install_complete_block(&mut state, &forged);
        let binding = state.votes.bind(
            forged.header(),
            schedule.head().consensus_committee_for_shard(ShardId::ROOT),
        );
        let actions = state.on_qc_result(block_hash, binding, Some(qc.clone()), vec![]);

        assert!(
            !actions
                .iter()
                .any(|a| matches!(a, Action::AttachCertifiedUncommitted { .. })),
            "got {actions:?}"
        );
        assert!(
            state
                .verification
                .cached_verified_certified_block(block_hash)
                .is_none()
        );
        assert!(state.pending_blocks.get_block(block_hash).is_none());
        assert!(
            actions.iter().any(|a| matches!(
                a,
                Action::StartBlockSync { target } if *target == genuine.height()
            )),
            "got {actions:?}"
        );

        install_complete_block(&mut state, &genuine);
        let actions = state.on_qc_result(block_hash, binding, Some(qc), vec![]);
        let attached = actions.iter().find_map(|a| match a {
            Action::AttachCertifiedUncommitted { certified } => Some(certified),
            _ => None,
        });
        assert!(
            attached.is_some_and(|certified| certified.block().tick_manifest().is_empty()),
            "got {actions:?}"
        );
    }

    #[test]
    fn a_commit_rearms_the_round_timer_at_the_rebased_timeout() {
        // A replica whose rounds ran ahead of its commits armed the round
        // timer at the backed-off timeout. The commit rebases the backoff and
        // is leader activity, so the timer must be armed afresh at the
        // rebased timeout from the commit, or the armed wakeup outlives the
        // deadline the timeout rule names.
        let (mut state, schedule) = make_test_state();
        state.set_time(LocalTimestamp::from_millis(100_000));
        let from = BlockHash::from_raw(Hash::from_bytes(b"lagging tip"));
        state.committed_height = BlockHeight::GENESIS;
        state.committed_hash = from;
        state.committed_block_anchor_wt = WeightedTimestamp::from_millis(500);
        state.view_change.view = Round::new(state.view_change.view_at_height_start.inner() + 5);
        let backed_off = state.current_view_change_timeout();

        let k1 = block_chained_on(BlockHeight::new(1), from, 1_500);
        let certified = Arc::new(Verified::new_unchecked_for_test(
            CertifiedBlock::new_unchecked(k1.clone(), make_test_qc(k1.hash(), k1.height())),
        ));
        let commit = state.on_block_ready_to_commit(&schedule, certified, CommitSource::Aggregator);
        assert_eq!(state.committed_height, BlockHeight::new(1));

        let rebased = state.current_view_change_timeout();
        assert!(rebased < backed_off, "{rebased:?} vs {backed_off:?}");
        let armed: Vec<Duration> = commit
            .iter()
            .filter_map(|action| match action {
                Action::SetTimer {
                    id: TimerId::ViewChange,
                    duration,
                } => Some(*duration),
                _ => None,
            })
            .collect();
        assert_eq!(armed, vec![rebased], "got {commit:?}");
    }

    #[test]
    fn start_block_sync_forwards_a_raised_target_while_syncing() {
        // The FSM owns the target: a higher one arriving mid-sync extends
        // the sync, and one the applied frontier already covers is met
        // before any fetch and does not enter sync mode.
        let (mut state, _topology_schedule) = make_test_state();
        state.set_time(LocalTimestamp::from_millis(100_000));
        state.committed_height = BlockHeight::new(3);
        state.block_sync.mark_applied(
            BlockHeight::new(4),
            BlockHash::from_raw(Hash::from_bytes(b"h4")),
        );

        assert!(state.start_block_sync(BlockHeight::new(4)).is_empty());
        assert!(!state.is_block_syncing());

        let first = state.start_block_sync(BlockHeight::new(10));
        assert!(state.is_block_syncing());
        assert!(first.iter().any(|a| matches!(
            a,
            Action::StartBlockSync { target } if *target == BlockHeight::new(10)
        )));

        let raised = state.start_block_sync(BlockHeight::new(12));
        assert!(
            raised.iter().any(|a| matches!(
                a,
                Action::StartBlockSync { target } if *target == BlockHeight::new(12)
            )),
            "got {raised:?}"
        );
    }

    #[test]
    fn sync_recovers_hole_left_by_failed_qc_verification() {
        // A synced block that fails QC verification leaves a gap with
        // verified entries stranded above it. The re-fetched replacement
        // arrives above `committed + 1` (admission runs ahead of the lagging
        // round-contiguous commit), so it lands in the buffer — and the
        // drain must reach down to that hole instead of starting above the
        // stranded heights, or sync wedges until restart.
        let (mut state, topology_schedule) = make_test_state();
        state.set_time(LocalTimestamp::from_millis(100_000));
        state.committed_height = BlockHeight::new(3);
        state.committed_hash = BlockHash::from_raw(Hash::from_bytes(b"anchor_parent"));
        state.set_block_syncing(true);
        // Height 4 admitted to chain state, commit lagging a block behind.
        let (hash4, _) = deliver_synced(
            &mut state,
            &topology_schedule,
            block_with_parent_qc_ts(BlockHeight::new(4), 90),
        );
        let _ = state.on_qc_signature_verified(
            &topology_schedule,
            QcSubject::SyncedBlock(hash4),
            Ok(make_test_qc(hash4, BlockHeight::new(4))),
        );
        assert_eq!(state.block_sync.sync_applied_height(), BlockHeight::new(4));

        let deliver = |state: &mut ShardCoordinator, height: u64, parent: BlockHash, ts: u64| {
            deliver_synced(
                state,
                &topology_schedule,
                block_chained_on(BlockHeight::new(height), parent, ts),
            )
        };

        let (hash5, actions) = deliver(&mut state, 5, hash4, 100);
        assert!(
            actions
                .iter()
                .any(|a| matches!(a, Action::VerifyQcSignature { .. }))
        );
        let (hash6, _) = deliver(&mut state, 6, hash5, 110);
        let (hash7, _) = deliver(&mut state, 7, hash6, 120);

        // 6 and 7 verify; 5 fails (Byzantine peer served a forged QC).
        for (hash, height) in [(hash6, 6), (hash7, 7)] {
            let qc = make_test_qc(hash, BlockHeight::new(height));
            let _ = state.on_qc_signature_verified(
                &topology_schedule,
                QcSubject::SyncedBlock(hash),
                Ok(qc),
            );
        }
        let _ = state.on_qc_signature_verified(
            &topology_schedule,
            QcSubject::SyncedBlock(hash5),
            Err(QcVerifyError::InvalidSignature),
        );

        // The honest replacement at height 5 buffers (5 > committed + 1) and
        // must drain into a fresh verification despite 6 and 7 pending above.
        let (hash5b, actions) = deliver(&mut state, 5, hash4, 200);
        assert_ne!(hash5b, hash5);
        assert!(
            actions
                .iter()
                .any(|a| matches!(a, Action::VerifyQcSignature { .. })),
            "re-fetched block at the hole must resubmit for verification; got {actions:?}"
        );
    }

    #[test]
    fn sync_applies_certified_sibling_at_already_applied_height() {
        // HotStuff-2 fork-safety allows two QCs to certify sibling blocks
        // at one height, and a peer can serve block sync the sibling that
        // never commits. The committing sibling's later delivery must
        // still verify and apply — buried below the applied frontier, the
        // round-contiguous commit walk defers forever on its missing
        // handle and the node wedges on a height it believes is synced.
        let (mut state, topology_schedule) = make_test_state();
        state.set_time(LocalTimestamp::from_millis(100_000));
        state.committed_height = BlockHeight::new(3);
        state.committed_hash = BlockHash::from_raw(Hash::from_bytes(b"anchor_parent"));
        state.set_block_syncing(true);

        let deliver = |state: &mut ShardCoordinator, height: u64, ts: u64| {
            let block = block_with_parent_qc_ts(BlockHeight::new(height), ts);
            let block_hash = block.hash();
            let mut signers = SignerBitfield::new(4);
            signers.set(0);
            signers.set(1);
            signers.set(2);
            let qc = QuorumCertificate::new(
                block_hash,
                ShardId::ROOT,
                BlockHeight::new(height),
                block.header().parent_block_hash(),
                block.header().round(),
                signers,
                AggregateSignature::ZERO,
                WeightedTimestamp::from_millis(ts),
            );
            let actions = state.on_sync_block_ready_to_apply(
                &topology_schedule,
                CertifiedBlock::new_unchecked(block, qc),
            );
            (block_hash, actions)
        };

        // The losing sibling at height 4 arrives first and applies.
        let (loser, actions) = deliver(&mut state, 4, 100);
        assert!(
            actions
                .iter()
                .any(|a| matches!(a, Action::VerifyQcSignature { .. }))
        );
        let qc = make_test_qc(loser, BlockHeight::new(4));
        let _ = state.on_qc_signature_verified(
            &topology_schedule,
            QcSubject::SyncedBlock(loser),
            Ok(qc),
        );
        assert_eq!(state.block_sync.sync_applied_height(), BlockHeight::new(4));

        // The committing sibling arrives on a re-fetch at the same height.
        let (winner, actions) = deliver(&mut state, 4, 200);
        assert_ne!(winner, loser);
        assert!(
            actions
                .iter()
                .any(|a| matches!(a, Action::VerifyQcSignature { .. })),
            "certified sibling at an applied height must resubmit for verification; got {actions:?}"
        );
        let qc = make_test_qc(winner, BlockHeight::new(4));
        let _ = state.on_qc_signature_verified(
            &topology_schedule,
            QcSubject::SyncedBlock(winner),
            Ok(qc),
        );

        // Both siblings' handles are cached; the two-chain rule commits
        // whichever one a round-contiguous child extends.
        assert!(
            state
                .verification
                .cached_verified_certified_block(loser)
                .is_some()
        );
        assert!(
            state
                .verification
                .cached_verified_certified_block(winner)
                .is_some(),
            "the committing sibling's handle must be available to the commit walk"
        );
    }

    /// Deliver `block` to the sync apply path under a synthetic 3-of-4 QC,
    /// returning its hash and the dispatched actions.
    fn deliver_synced(
        state: &mut ShardCoordinator,
        topology_schedule: &TopologySchedule,
        block: Block,
    ) -> (BlockHash, Vec<Action>) {
        let block_hash = block.hash();
        let mut signers = SignerBitfield::new(4);
        signers.set(0);
        signers.set(1);
        signers.set(2);
        let qc = QuorumCertificate::new(
            block_hash,
            ShardId::ROOT,
            block.height(),
            block.header().parent_block_hash(),
            block.header().round(),
            signers,
            AggregateSignature::ZERO,
            WeightedTimestamp::from_millis(100),
        );
        let actions = state.on_sync_block_ready_to_apply(
            topology_schedule,
            CertifiedBlock::new_unchecked(block, qc),
        );
        (block_hash, actions)
    }

    /// A QC certifying `block` whose committable block is the header's
    /// parent, as a live QC on the block would carry.
    fn qc_on(block: &Block) -> Verified<QuorumCertificate> {
        let mut signers = SignerBitfield::new(4);
        signers.set(0);
        signers.set(1);
        signers.set(2);
        // SAFETY: synthetic test fixture, no real signature.
        Verified::<QuorumCertificate>::new_unchecked_for_test(QuorumCertificate::new(
            block.hash(),
            ShardId::ROOT,
            block.height(),
            block.header().parent_block_hash(),
            block.header().round(),
            signers,
            AggregateSignature::ZERO,
            WeightedTimestamp::from_millis(110),
        ))
    }

    /// A coordinator over `committee`'s single-shard topology, synced to
    /// height 3 with a sibling of the chain's block applied at 4 — the
    /// block a peer served that never commits — and the chain's block
    /// there.
    fn applied_orphan_at_four(
        committee: &test_utils::TestCommittee,
    ) -> (ShardCoordinator, TopologySchedule, Block) {
        let topology_schedule = TopologySchedule::single(Arc::new(committee.topology_snapshot(1)));
        let mut state = ShardCoordinator::new(
            Arc::new(BlsVerifier),
            ShardId::ROOT,
            ShardConsensusConfig::default(),
            RecoveredState::default(),
            WeightedTimestamp::ZERO,
        )
        .signed_by(ValidatorId::new(0));
        state.set_time(LocalTimestamp::from_millis(100_000));
        state.committed_height = BlockHeight::new(3);
        state.committed_hash = BlockHash::from_raw(Hash::from_bytes(b"anchor_parent"));
        state.set_block_syncing(true);

        let (orphan, _) = deliver_synced(
            &mut state,
            &topology_schedule,
            block_with_parent_qc_ts(BlockHeight::new(4), 100),
        );
        let _ = state.on_qc_signature_verified(
            &topology_schedule,
            QcSubject::SyncedBlock(orphan),
            Ok(make_test_qc(orphan, BlockHeight::new(4))),
        );
        assert_eq!(state.block_sync.sync_applied_height(), BlockHeight::new(4));

        // The winner extends the same committed tip; a different parent
        // stamp keeps it a distinct block from the orphan.
        let winner = block_with_parent_qc_ts(BlockHeight::new(4), 105);
        (state, topology_schedule, winner)
    }

    #[test]
    fn orphan_sibling_at_applied_height_reopens_the_height() {
        // A peer served the sibling at height 4 that never commits. The
        // child at 5 arrives naming the other sibling, whose header this
        // node does not hold, so nothing here dates the child's committee:
        // the child's own anchor names the window its child opens, a
        // different committee whenever the winner is the last block its
        // epoch anchors. The child's parent QC proves the winner certified,
        // so the height goes back to the FSM while the child waits. The FSM
        // holds an applied height out of its window, so this is the only
        // path by which the winner arrives.
        let committee = test_utils::TestCommittee::new(4, 7);
        let (mut state, topology_schedule, winner) = applied_orphan_at_four(&committee);
        let winner_hash = winner.hash();
        let child = test_utils::signed_child_block(
            &committee,
            &winner,
            Round::new(5),
            WeightedTimestamp::from_millis(110),
        );
        let child_qc = qc_on(&child);
        let (child_hash, actions) = deliver_synced(&mut state, &topology_schedule, child);
        assert!(
            actions.iter().any(|a| matches!(
                a,
                Action::ReopenSyncHeight { height, hash }
                    if *height == BlockHeight::new(4) && *hash == winner_hash
            )),
            "the reopen names the sibling the child extends; got {actions:?}"
        );
        assert!(
            !actions
                .iter()
                .any(|a| matches!(a, Action::VerifyQcSignature { .. })),
            "no committee is guessed for a child whose parent is missing; got {actions:?}"
        );
        assert!(
            state
                .block_sync
                .has_buffered(BlockHeight::new(5), &child_hash)
        );

        // The winner arrives on the reopened height, and once it applies
        // the child drains against the committee the winner anchors.
        let (delivered, _) = deliver_synced(&mut state, &topology_schedule, winner);
        assert_eq!(delivered, winner_hash);
        let actions = state.on_qc_signature_verified(
            &topology_schedule,
            QcSubject::SyncedBlock(winner_hash),
            Ok(make_test_qc(winner_hash, BlockHeight::new(4))),
        );
        assert!(
            actions.iter().any(|a| matches!(
                a,
                Action::VerifyQcSignature { subject: QcSubject::SyncedBlock(hash), .. } if *hash == child_hash
            )),
            "the child drains once its parent applies; got {actions:?}"
        );
        assert_eq!(
            state.committed_height,
            BlockHeight::new(3),
            "nothing commits before the child's QC"
        );

        // The child's QC commits the winner under it.
        let actions = state.on_qc_signature_verified(
            &topology_schedule,
            QcSubject::SyncedBlock(child_hash),
            Ok(child_qc),
        );
        assert!(
            actions.iter().any(|a| matches!(
                a,
                Action::Continuation(ProtocolEvent::BlockReadyToCommit { certified, .. })
                    if certified.block().hash() == winner_hash
            )),
            "the winner commits under the child's QC; got {actions:?}"
        );
    }

    #[test]
    fn a_child_whose_parent_qc_fails_reopens_nothing() {
        // The reopen names the block the fetch must return, so a parent QC
        // that does not verify cannot be allowed to name one: a peer could
        // otherwise point the FSM at a hash nobody holds.
        let committee = test_utils::TestCommittee::new(4, 7);
        let (mut state, topology_schedule, winner) = applied_orphan_at_four(&committee);
        let strangers = test_utils::TestCommittee::new(4, 8);
        let child = test_utils::signed_child_block(
            &strangers,
            &winner,
            Round::new(5),
            WeightedTimestamp::from_millis(110),
        );
        let (child_hash, actions) = deliver_synced(&mut state, &topology_schedule, child);
        assert!(actions.is_empty(), "got {actions:?}");
        assert!(
            !state
                .block_sync
                .has_buffered(BlockHeight::new(5), &child_hash)
        );
    }

    #[test]
    fn parentless_blocks_filling_a_height_do_not_shut_out_the_chains_block() {
        // Height 4 is applied and commits only under its child at 5, which
        // enters through the buffer at 5. A peer has answered every fetch
        // of 5 with a block naming a parent nobody holds: none can be
        // verified, and each waits for a parent until 4 commits. Were
        // they to keep the height's slots against the chain's own block,
        // 4 would never commit and the sync would stop here for good.
        let (mut state, topology_schedule) = make_test_state();
        state.set_time(LocalTimestamp::from_millis(100_000));
        state.committed_height = BlockHeight::new(3);
        state.committed_hash = BlockHash::from_raw(Hash::from_bytes(b"anchor_parent"));
        state.set_block_syncing(true);

        let (parent, _) = deliver_synced(
            &mut state,
            &topology_schedule,
            block_with_parent_qc_ts(BlockHeight::new(4), 100),
        );
        let _ = state.on_qc_signature_verified(
            &topology_schedule,
            QcSubject::SyncedBlock(parent),
            Ok(make_test_qc(parent, BlockHeight::new(4))),
        );

        for i in 0..4u8 {
            let unknown = BlockHash::from_raw(Hash::from_bytes(&[i; 8]));
            let (fake, actions) = deliver_synced(
                &mut state,
                &topology_schedule,
                block_chained_on(BlockHeight::new(5), unknown, 110),
            );
            assert!(actions.is_empty(), "got {actions:?}");
            assert!(state.block_sync.has_buffered(BlockHeight::new(5), &fake));
        }

        let child = block_chained_on(BlockHeight::new(5), parent, 110);
        let child_qc = qc_on(&child);
        let (child_hash, actions) = deliver_synced(&mut state, &topology_schedule, child);
        assert!(
            actions.iter().any(|a| matches!(
                a,
                Action::VerifyQcSignature { subject: QcSubject::SyncedBlock(hash), .. }
                    if *hash == child_hash
            )),
            "the chain's block goes to verification past the parentless ones; got {actions:?}"
        );
        let actions = state.on_qc_signature_verified(
            &topology_schedule,
            QcSubject::SyncedBlock(child_hash),
            Ok(child_qc),
        );
        assert!(
            actions.iter().any(|a| matches!(
                a,
                Action::Continuation(ProtocolEvent::BlockReadyToCommit { certified, .. })
                    if certified.block().hash() == parent
            )),
            "the applied parent commits under its child; got {actions:?}"
        );
    }

    #[test]
    fn child_of_the_applied_block_does_not_reopen_its_height() {
        // The companion: the child's parent QC names the block this node
        // applied, so the commit walks through and no refetch is asked for.
        let (mut state, topology_schedule) = make_test_state();
        state.set_time(LocalTimestamp::from_millis(100_000));
        state.committed_height = BlockHeight::new(3);
        // The commit prefix walks from the applied block down to the
        // committed tip, so the tip has to be the parent it extends.
        state.committed_hash = BlockHash::from_raw(Hash::from_bytes(b"anchor_parent"));
        state.set_block_syncing(true);

        let (parent, _) = deliver_synced(
            &mut state,
            &topology_schedule,
            block_with_parent_qc_ts(BlockHeight::new(4), 100),
        );
        let qc = make_test_qc(parent, BlockHeight::new(4));
        let _ = state.on_qc_signature_verified(
            &topology_schedule,
            QcSubject::SyncedBlock(parent),
            Ok(qc),
        );

        let child = block_chained_on(BlockHeight::new(5), parent, 110);
        let child_qc = qc_on(&child);
        let (child_hash, _) = deliver_synced(&mut state, &topology_schedule, child);
        let actions = state.on_qc_signature_verified(
            &topology_schedule,
            QcSubject::SyncedBlock(child_hash),
            Ok(child_qc),
        );
        assert!(
            !actions
                .iter()
                .any(|a| matches!(a, Action::ReopenSyncHeight { .. })),
            "got {actions:?}"
        );
        assert!(
            actions.iter().any(|a| matches!(
                a,
                Action::Continuation(ProtocolEvent::BlockReadyToCommit { certified, .. })
                    if certified.block().hash() == parent
            )),
            "the applied parent commits under its round-contiguous child; got {actions:?}"
        );
    }

    #[test]
    fn parent_qc_result_leaves_a_synced_block_of_the_same_hash_waiting() {
        // One block is in flight on both QC paths: its header arrived
        // through consensus, which verifies the `parent_qc` it carries,
        // while sync fetched the block with its own QC. The parent QC
        // certifies height 3, so its result must not settle the synced
        // block at height 4; only the block's own QC does.
        let (mut state, topology_schedule) = make_multi_validator_state_at(1);
        state.set_time(LocalTimestamp::from_millis(100_000));
        let parent_hash = BlockHash::from_raw(Hash::from_bytes(b"anchor_parent"));
        state.committed_height = BlockHeight::new(3);
        state.committed_hash = parent_hash;

        let mut signers = SignerBitfield::new(4);
        signers.set(0);
        signers.set(1);
        signers.set(2);
        let parent_qc = QuorumCertificate::new(
            parent_hash,
            ShardId::ROOT,
            BlockHeight::new(3),
            BlockHash::ZERO,
            Round::new(3),
            signers,
            AggregateSignature::ZERO,
            WeightedTimestamp::from_millis(99_000),
        );
        let template = make_header_at_height(BlockHeight::new(4), 100_000);
        let header = BlockHeader::new(BlockHeaderParts {
            shard_id: template.shard_id(),
            height: template.height(),
            parent_block_hash: parent_hash,
            parent_qc: parent_qc.into(),
            proposer: template.proposer(),
            timestamp: template.timestamp(),
            round: template.round(),
            load: template.load(),
            ..Default::default()
        });
        let block = Block::Live {
            header,
            transactions: Arc::new(Capped::empty()),
            certificates: Arc::new(Capped::empty()),
            provisions: Arc::new(Capped::empty()),
            abandonment_records: Arc::new(Capped::empty()),
            state_claims: Arc::new(Capped::empty()),
            tick_manifest: Arc::new(Capped::empty()),
            terms: Arc::new(Capped::empty()),
            witness_sources: Arc::new(WitnessSources::empty()),
        };
        let block_hash = block.hash();
        let actions = state.on_block_header(
            &topology_schedule,
            block.header(),
            BlockManifest::default(),
            |_| None,
            |_| None,
            |_| None,
        );
        assert!(
            actions.iter().any(|a| matches!(
                a,
                Action::VerifyQcSignature { subject: QcSubject::ParentOf(h), .. } if *h == block_hash
            )),
            "got {actions:?}"
        );

        state.set_block_syncing(true);
        let (_, actions) = deliver_synced(&mut state, &topology_schedule, block.clone());
        assert!(
            actions.iter().any(|a| matches!(
                a,
                Action::VerifyQcSignature { subject: QcSubject::SyncedBlock(h), .. } if *h == block_hash
            )),
            "got {actions:?}"
        );

        // SAFETY: synthetic test fixture, parent_qc built locally.
        let parent_qc = Verified::<QuorumCertificate>::new_unchecked_for_test(
            block.header().parent_qc().clone(),
        );
        let _ = state.on_qc_signature_verified(
            &topology_schedule,
            QcSubject::ParentOf(block_hash),
            Ok(parent_qc),
        );
        assert!(state.block_sync.has_pending_verification(&block_hash));
        assert_ne!(state.block_sync.sync_applied_height(), BlockHeight::new(4));

        let _ = state.on_qc_signature_verified(
            &topology_schedule,
            QcSubject::SyncedBlock(block_hash),
            Ok(qc_on(&block)),
        );
        assert_eq!(state.block_sync.sync_applied_height(), BlockHeight::new(4));
        assert!(
            state
                .verification
                .cached_verified_certified_block(block_hash)
                .is_some()
        );
    }

    #[test]
    fn test_syncing_validator_can_vote_for_others_blocks() {
        // Syncing only blocks us from proposing content; we still vote on others'
        // blocks once verification completes.
        let (mut state, topology_schedule) = make_multi_validator_state();
        state.set_time(LocalTimestamp::from_millis(100_000));
        state.set_block_syncing(true);

        // A fresh state's current round is 1, so vote at the matching round.
        let header = empty_block_at_round(state.committed_hash, 1)
            .header()
            .clone();
        let block_hash = header.hash();
        let height = header.height();
        let round = header.round();
        state.pending_blocks.insert(PendingBlock::from_manifest(
            header,
            BlockManifest::default(),
            LocalTimestamp::ZERO,
        ));
        state.answers.measured(
            block_hash,
            AnswerDelta::default(),
            AnswerAdditions::default(),
        );
        let actions = state.try_vote_on_block(&topology_schedule, block_hash, height, round);

        assert!(
            actions
                .iter()
                .any(|a| matches!(a, Action::SignAndBroadcastBlockVote { .. }))
        );
        assert_eq!(state.sole().last_voted_round, round);
    }

    #[test]
    fn test_view_changes_allowed_during_sync() {
        // Syncing nodes still participate in view changes — they must help
        // advance the view if the leader fails, otherwise the chain stalls
        // while they catch up.
        let (mut state, topology_schedule) = make_test_state();
        state.set_time(LocalTimestamp::from_millis(100_000));
        state.view_change.last_leader_activity = Some(LocalTimestamp::ZERO);

        assert!(state.should_advance_round(&topology_schedule));
        state.set_block_syncing(true);
        assert!(state.should_advance_round(&topology_schedule));
        assert!(state.check_round_timeout(&topology_schedule).is_some());
    }

    #[test]
    fn test_sync_mode_resets_leader_activity_on_exit() {
        // Leaving sync resets leader activity to `now` so the fresh round doesn't
        // immediately time out on stale activity from before sync started.
        let (mut state, topology_schedule) = make_test_state();
        state.set_time(LocalTimestamp::from_millis(100_000));
        state.view_change.last_leader_activity = Some(LocalTimestamp::ZERO);

        state.set_block_syncing(true);
        state.on_block_sync_complete(&topology_schedule);

        assert_eq!(
            state.view_change.last_leader_activity,
            Some(LocalTimestamp::from_millis(100_000))
        );
    }

    /// A block the vote fence withheld does not buy the progress
    /// window.
    ///
    /// The window is for work this replica finishes on its own. A block
    /// held at the fence waits on a counterpart to answer for a claim
    /// its proposer made, and a silent counterpart never answers — so
    /// the wait is bounded by the round timer, as every other wait on
    /// somebody else is. Priced the other way, one claim nobody can
    /// check stalls every transaction beside it for three rounds.
    #[test]
    fn a_block_held_at_the_fence_times_out_on_the_round_and_not_the_window() {
        let (mut state, topology_schedule) = make_test_state();
        let round = state.view_change.view;
        let height = BlockHeight::new(state.committed_height.inner() + 1);
        let header = BlockHeader::new(BlockHeaderParts {
            shard_id: state.local_shard,
            height,
            round,
            proposer: topology_schedule
                .head()
                .proposer_for(state.local_shard, round),
            ..Default::default()
        });
        let hash = header.hash();
        state.pending_blocks.insert(PendingBlock::from_manifest(
            header,
            BlockManifest::default(),
            LocalTimestamp::ZERO,
        ));

        // Past the round timeout, inside the progress window.
        state.view_change.last_leader_activity = Some(LocalTimestamp::ZERO);
        state.set_time(
            LocalTimestamp::ZERO
                .plus(state.current_view_change_timeout() + Duration::from_millis(1)),
        );
        assert!(
            !state.should_advance_round(&topology_schedule),
            "content still landing here is worth the window",
        );

        state
            .pending_blocks
            .get_mut(hash)
            .expect("the block was just inserted")
            .set_awaiting_counterpart(true);
        assert!(
            state.should_advance_round(&topology_schedule),
            "a block waiting on a counterpart is not, and the round timer bounds it",
        );
    }

