    #[test]
    fn test_sync_block_with_subquorum_qc_is_rejected_before_verification() {
        // A synced block whose QC has only one signer in a 4-validator
        // committee (1f+1, not 2f+1) must be rejected before reaching the
        // signature-only `VerifyQcSignature` action. Without this gate a Byzantine
        // peer can fork the local chain by serving a self-signed block.
        let (mut state, topology_schedule) = make_test_state();
        state.set_time(LocalTimestamp::from_millis(100_000));

        let block = Block::Live {
            header: {
                let __h = make_header_at_height(BlockHeight::new(1), 1000);
                BlockHeader::new(BlockHeaderParts {
                    shard_id: __h.shard_id(),
                    height: __h.height(),
                    parent_block_hash: BlockHash::ZERO,
                    parent_qc: __h.parent_qc().clone().into(),
                    proposer: __h.proposer(),
                    timestamp: ProposerTimestamp::from_millis(1000),
                    round: __h.round(),
                    is_fallback: __h.is_fallback(),
                    state_root: __h.state_root(),
                    body_root: __h.body_root(),
                    provision_tx_roots: __h.provision_tx_roots().clone(),
                    txs_in_flight: __h.txs_in_flight(),
                    ..Default::default()
                })
            },
            transactions: Arc::new(Capped::empty()),
            certificates: Arc::new(Capped::empty()),
            provisions: Arc::new(Capped::empty()),
            witness_sources: Arc::new(WitnessSources::empty()),
            abandonment_records: Arc::new(Capped::empty()),
            state_claims: Arc::new(Capped::empty()),
            tick_manifest: Arc::new(Capped::empty()),
            terms: Arc::new(Capped::empty()),
        };
        let mut sub_quorum_signers = SignerBitfield::new(4);
        sub_quorum_signers.set(0); // single signer — far below 2f+1 = 3
        let qc = {
            let __qc = make_test_qc(block.hash(), BlockHeight::new(1));
            QuorumCertificate::new(
                __qc.block_hash(),
                __qc.shard_id(),
                __qc.height(),
                __qc.parent_block_hash(),
                __qc.round(),
                sub_quorum_signers,
                __qc.aggregated_signature(),
                WeightedTimestamp::from_millis(1000),
            )
        };
        let certified = CertifiedBlock::new_unchecked(block, qc);

        let actions = state.on_sync_block_ready_to_apply(&topology_schedule, certified);
        assert!(
            actions.is_empty(),
            "sub-quorum sync block must produce no VerifyQcSignature dispatch"
        );
        assert!(
            !actions
                .iter()
                .any(|a| matches!(a, Action::VerifyQcSignature { .. })),
            "must not reach signature verification with sub-quorum signers"
        );
    }

    #[test]
    #[should_panic(expected = "commit linkage broken")]
    fn commit_panics_when_block_does_not_extend_committed_tip() {
        // Defense-in-depth: a block whose parent isn't the committed tip means
        // a fork slipped past the safe-vote / round-contiguous rules, so the
        // commit path fails fast rather than splicing a divergent chain on.
        let (mut state, topology_schedule) = make_test_state();
        state.committed_height = BlockHeight::new(0);
        state.committed_hash = BlockHash::from_raw(Hash::from_bytes(b"real-tip"));

        // A height-1 block that extends some other block, not the committed tip.
        let block = Block::Live {
            header: {
                let __h = make_header_at_height(BlockHeight::new(1), 1000);
                BlockHeader::new(BlockHeaderParts {
                    shard_id: __h.shard_id(),
                    height: __h.height(),
                    parent_block_hash: BlockHash::from_raw(Hash::from_bytes(b"wrong-parent")),
                    parent_qc: __h.parent_qc().clone().into(),
                    proposer: __h.proposer(),
                    timestamp: ProposerTimestamp::from_millis(1000),
                    round: __h.round(),
                    is_fallback: __h.is_fallback(),
                    state_root: __h.state_root(),
                    body_root: __h.body_root(),
                    provision_tx_roots: __h.provision_tx_roots().clone(),
                    txs_in_flight: __h.txs_in_flight(),
                    ..Default::default()
                })
            },
            transactions: Arc::new(Capped::empty()),
            certificates: Arc::new(Capped::empty()),
            provisions: Arc::new(Capped::empty()),
            witness_sources: Arc::new(WitnessSources::empty()),
            abandonment_records: Arc::new(Capped::empty()),
            state_claims: Arc::new(Capped::empty()),
            tick_manifest: Arc::new(Capped::empty()),
            terms: Arc::new(Capped::empty()),
        };
        let block_hash = block.hash();
        // The linkage assert fires before the committee resolves, so a
        // placeholder QC suffices.
        let _ = state.record_block_committed(
            &topology_schedule,
            &block,
            block_hash,
            &QuorumCertificate::genesis(
                block.header().shard_id(),
                ChainOrigin::root(WeightedTimestamp::ZERO),
            ),
            WeightedTimestamp::from_millis(1000),
        );
    }

    /// A derivation holding no record a transaction names: the shape of
    /// a replica syncing into a shard whose transactions name components
    /// seated where it has never been.
    struct RecordsElsewhere;

    impl Derivation for RecordsElsewhere {
        fn derive(&self, _vm: &TransactionEnvelope) -> Result<Derived, DerivationError> {
            Err(DerivationError::Unresolved(Unresolved {
                instances: vec![Address::new([0x77; 31], AddressClass::Component)],
                packages: Vec::new(),
            }))
        }

        fn declared(&self, vm: &TransactionEnvelope) -> Result<Declared, DerivationError> {
            test_utils::StubVmStatics.declared(vm)
        }
    }

    /// A synced block is certified, so its state-root verification
    /// prepares its tree without judging it at the parent: the parent
    /// rules read each transaction's routing, and a replica syncing in
    /// may route none of a transaction whose payer this shard holds.
    #[test]
    fn a_synced_block_is_not_judged_at_its_parent() {
        let (mut state, topology_schedule) = make_test_state();
        state.set_time(LocalTimestamp::from_millis(100_000));

        let payer = PrincipalAddr::new([0x42; 31]);
        let signed = test_utils::stub_transaction(
            payer,
            &[payer.address()],
            1,
            TimestampRange::new(
                WeightedTimestamp::ZERO,
                WeightedTimestamp::from_millis(60_000),
            ),
        );
        let unrouted = Transaction::new(signed.body().clone());
        let gap = unrouted
            .try_derived(&RecordsElsewhere)
            .expect_err("no record the transaction names is seated here");
        assert!(gap.unresolved().is_some(), "a gap, not a refusal");
        assert!(!unrouted.is_routed());

        let block = make_live_block(
            ShardId::ROOT,
            BlockHeight::new(1),
            1_000,
            ValidatorId::new(1),
            vec![Arc::new(unrouted)],
            vec![],
        );
        let qc = make_test_qc(block.hash(), BlockHeight::new(1));
        let _ = state.apply_synced_block(&topology_schedule, block, qc);

        let ready = state.drain_ready_state_root_verifications();
        assert_eq!(ready.len(), 1, "the synced block's tree is prepared");
        let parent = MemberIndex::empty(ShardId::ROOT);
        for verification in &ready {
            // What the verification handler does with the entry.
            if let Some(judgement) = &verification.parent_judgement {
                let _ = refused_at_parent(
                    &AtParent {
                        local: ShardId::ROOT,
                        creations: &verification.creations,
                        members: &verification.members,
                        fence: &judgement.fence,
                        state_claims: &verification.state_claims,
                        transactions: &verification.transactions,
                        finalizations: &verification.finalizations,
                    },
                    &parent,
                );
            }
        }
        assert!(ready[0].parent_judgement.is_none());
    }

